import { useEffect, useRef } from 'react';

interface UseScrollSentinelOptions {
  onIntersect: () => void;
  enabled: boolean;
  rootMargin?: string;
}

export function useScrollSentinel({
  onIntersect,
  enabled,
  rootMargin = '400px',
}: UseScrollSentinelOptions) {
  const sentinelRef = useRef<HTMLDivElement>(null);
  const callbackRef = useRef(onIntersect);
  callbackRef.current = onIntersect;

  useEffect(() => {
    const el = sentinelRef.current;
    if (!el || !enabled) return;

    const observer = new IntersectionObserver(
      (entries) => {
        if (entries[0]?.isIntersecting) {
          callbackRef.current();
        }
      },
      { rootMargin }
    );

    observer.observe(el);
    return () => observer.disconnect();
  }, [enabled, rootMargin]);

  return sentinelRef;
}

import { useLocation, useNavigate } from "@tanstack/react-router";
import {
	ArrowUp,
	ChevronDown,
	ChevronRight,
	ChevronUp,
	History,
	Inbox,
	MessageSquare,
} from "lucide-react";
import { useCallback, useEffect, useMemo, useState } from "react";
import { extractOAuthDomain } from "@/components/connectors/connector-display";
import type { ConnectorSelectorItem } from "@/components/connectors/connector-selector";
import { useOptionalMemoryConnectorGroups } from "@/components/memory/memory-connector-groups";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
	Collapsible,
	CollapsibleContent,
	CollapsibleTrigger,
} from "@/components/ui/collapsible";
import { Skeleton } from "@/components/ui/skeleton";
import { Spinner } from "@/components/ui/spinner";
import { TooltipProvider } from "@/components/ui/tooltip";
import { useAgentBehaviorsList } from "@/hooks/use-behaviors";
import { useCurrentOrg } from "@/hooks/use-current-org";
import { useDebounce } from "@/hooks/use-debounce";
import { useScrollSentinel } from "@/hooks/use-scroll-sentinel";
import { useTabFilters } from "@/hooks/use-tab-filters";
import {
	useAgents,
	useConnectorDefinitions,
	useEntityClassifiers,
	useEntityTypes,
	useInfiniteContentWithFilters,
	usePublicConnectorDefinitions,
	usePublicEntityClassifiers,
	usePublicInfiniteContentWithFilters,
} from "@/lib/api";
import { useClientActivityScopes } from "@/lib/api/client-activity-scopes";
import { useConnectedClients } from "@/lib/api/clients";
import { useAllFeeds, useConnections } from "@/lib/api/connections";
import { useSchedules } from "@/lib/api/schedules";
import { useAuthState } from "@/lib/auth-state";
import { groupClients } from "@/lib/connectors/client-rows";
import {
	resolveConnectionFilterLabel,
	resolveFeedFilterLabel,
} from "@/lib/event-filter-labels";
import {
	applyEventTabDefaults,
	type ClassificationFilters,
	hasActiveFilters as checkActiveFilters,
	EVENT_FILTER_KEYS,
	isDateFeedMode,
	type PartialEventFilters,
	parseEventFiltersFromUrl,
	serializeEventFiltersToSearch,
} from "@/lib/event-filters";
import { formatShortDate, formatTimeAgo } from "@/lib/format-utils";
import { parseScheduleScope } from "@/lib/memory-browse";
import {
	agentFeedsSourceLink,
	behaviorSourceLink,
	clientSourceLink,
	connectionSourceLink,
	type DrillSourceLink,
	feedSourceLink,
	scheduleSourceLink,
} from "@/lib/memory-drill-links";
import { cn, FILLED_BOX } from "@/lib/utils";
import { EntityLinkCell } from "../entity-link-cell";
import { TabEmptyState, TabErrorState } from "../tab-states";
import { ClientFilterDetails, DrillFilterBanner } from "./drill-filter-banner";
import { EventCard } from "./event-card";
import { collectRelevantEventKinds } from "./event-kind-options";
import { EventsFilterBar } from "./events-filter-bar";
import { EventsTimeline } from "./events-timeline";
import {
	collapseSupersedeChains,
	groupContentByThread,
	mergeEventTabFilters,
} from "./navigation";
import { buildSampleEvents } from "./sample-events";

interface EventsTabProps {
	/**
	 * Org id when workspace is resolved. `null` during the cold-cache
	 * workspace-loading window (org-wide events landing only). When null,
	 * the filter-bar chrome still renders so the user sees the search +
	 * tabs from the first frame; the data queries stay disabled until
	 * workspace lands.
	 */
	organizationId: string | null;
	ownerSlug?: string; // Required for org-wide mode drill-down links
	entityId?: number; // Scope via prop (legacy) or the ?entity_id= URL filter
	/** Memory page filters sources in the sidebar rail. */
	hideSourceFilter?: boolean;
	/** Memory browse drill-down: force event queries to this entity type. */
	scopedEntityTypes?: string[];
}

interface ClassifierEntry {
	slug: string;
	name: string;
	values: string[];
	parentSlug: string | null;
	valuesByParentValue: Record<string, string[]>;
}

interface BehaviorClassifierGroup {
	behaviorName: string | null;
	classifiers: ClassifierEntry[];
}

/**
 * One node on the vertical timeline rail. The left gutter holds the dot and a
 * relative timestamp (absolute on hover); a connecting line runs the full
 * height and is hidden on the last row via `isLast` so the rail doesn't dangle
 * past the final event. Content (the borderless EventCard) sits on the right.
 */
function TimelineRow({
	occurredAt,
	isLast,
	children,
}: {
	occurredAt: string | Date | number | null | undefined;
	isLast?: boolean;
	children: React.ReactNode;
}) {
	return (
		<div className="relative flex gap-4 pb-6">
			{/* Rail: dot + connecting line. The line spans the full row height so
			    adjacent nodes read as one continuous timeline; `isLast` drops it on
			    the final row so the rail doesn't dangle past the last event. */}
			<div className="relative flex w-2.5 shrink-0 justify-center">
				{!isLast && (
					<div
						className="absolute top-1 bottom-[-1.5rem] left-1/2 w-px -translate-x-1/2 bg-border"
						aria-hidden
					/>
				)}
				<div className="relative z-10 mt-1 h-2.5 w-2.5 rounded-full border-2 border-background bg-muted-foreground/60" />
			</div>

			{/* Content column: timestamp header + event body */}
			<div className="min-w-0 flex-1">
				{occurredAt && (
					<time
						dateTime={new Date(occurredAt).toISOString()}
						title={formatShortDate(occurredAt)}
						className="mb-1 block text-xs leading-none text-muted-foreground"
					>
						{formatTimeAgo(occurredAt)}
					</time>
				)}
				{children}
			</div>
		</div>
	);
}

export function EventsTab({
	organizationId,
	ownerSlug,
	entityId,
	hideSourceFilter = false,
	scopedEntityTypes,
}: EventsTabProps) {
	const { isAuthenticated, isReady } = useAuthState();
	const { isMember, isLoading: isOrgLoading } = useCurrentOrg();
	const canManageWorkspace = isReady && isAuthenticated && isMember;
	const canReadPublicWorkspace =
		isReady && (!isAuthenticated || (!isOrgLoading && !isMember));

	const navigate = useNavigate();
	const location = useLocation();
	const scheduleScopeId = parseScheduleScope(location.search ?? {});

	const {
		filters: urlFilters,
		updateFilters: updateUrlFilters,
		clearFilters: clearUrlFilters,
	} = useTabFilters<PartialEventFilters>({
		parse: parseEventFiltersFromUrl,
		serialize: serializeEventFiltersToSearch,
		filterKeys: EVENT_FILTER_KEYS,
		merge: mergeEventTabFilters,
	});

	// Local search state (for debouncing)
	const [searchQuery, setSearchQuery] = useState(urlFilters.searchQuery || "");
	const debouncedSearch = useDebounce(searchQuery, 1000);

	// Combine URL filters with debounced search
	const filters = useMemo<PartialEventFilters>(
		() =>
			applyEventTabDefaults({
				...urlFilters,
				searchQuery: debouncedSearch.length >= 3 ? debouncedSearch : undefined,
				...(scopedEntityTypes?.length
					? { entityTypes: scopedEntityTypes }
					: {}),
			}),
		[urlFilters, debouncedSearch, scopedEntityTypes],
	);

	const updateFilters = updateUrlFilters;

	useEffect(() => {
		const normalizedSearch =
			debouncedSearch.length >= 3 ? debouncedSearch : undefined;
		if ((urlFilters.searchQuery || undefined) === normalizedSearch) {
			return;
		}
		updateUrlFilters({ searchQuery: normalizedSearch });
	}, [debouncedSearch, updateUrlFilters, urlFilters.searchQuery]);

	const clearFilters = () => {
		setSearchQuery("");
		clearUrlFilters();
	};

	const hasFilters = useMemo(
		() =>
			checkActiveFilters(
				applyEventTabDefaults({
					...urlFilters,
					searchQuery:
						debouncedSearch.length >= 3 ? debouncedSearch : undefined,
				}),
			),
		[urlFilters, debouncedSearch],
	);

	// Entity scope comes from either the prop (when embedded as an entity tab) or
	// the URL drill-down filter — the entity page's "See memory" deep-links into
	// the org-wide Memory page with ?entity_id=…. Both paths scope identically.
	const effectiveEntityId = entityId ?? filters.entityId ?? undefined;
	const isOrgWide = effectiveEntityId === undefined;

	// Fetch data — gate every auth/public fork on `isReady` so the bootstrap
	// window (isAuthenticated=false, isReady=false) doesn't fire the public
	// query and 404 against a private org before auth resolves.
	const { data: connectorDefinitions = [] } = useConnectorDefinitions(
		isReady && canManageWorkspace ? organizationId : null,
	);
	const { data: publicConnectorDefinitions = [] } =
		usePublicConnectorDefinitions(canReadPublicWorkspace ? ownerSlug : null);
	const effectiveConnectorDefinitions = canManageWorkspace
		? connectorDefinitions
		: publicConnectorDefinitions;
	const { data: workspaceEntityTypes = [] } = useEntityTypes(
		canManageWorkspace && organizationId ? { organizationId } : undefined,
	);

	const memoryConnectorGroups = useOptionalMemoryConnectorGroups();
	const connectionFilterIds = filters.connectionIds;
	const hasConnectionFilter = (connectionFilterIds?.length ?? 0) > 0;
	const { data: filteredConnections = [] } = useConnections(
		isReady && canManageWorkspace ? (organizationId ?? "") : "",
		{
			connectionIds: connectionFilterIds ?? undefined,
			enabled:
				!memoryConnectorGroups &&
				isReady &&
				canManageWorkspace &&
				hasConnectionFilter,
		},
	);
	const feedFilterIds = filters.feedIds;
	const hasFeedFilter = (feedFilterIds?.length ?? 0) > 0;
	const { data: workspaceFeeds = [] } = useAllFeeds(
		isReady && canManageWorkspace ? organizationId : null,
		{
			feedIds: feedFilterIds ?? undefined,
			enabled: isReady && canManageWorkspace && hasFeedFilter,
		},
	);

	const connectionLabelSources = useMemo(() => {
		if (memoryConnectorGroups) {
			return memoryConnectorGroups.groups.flatMap((group) =>
				group.connections.map((connection) => ({
					id: connection.id,
					display_name: connection.display_name,
					connector_name: group.connector_name,
					connector_key: group.connector_key,
				})),
			);
		}
		return filteredConnections;
	}, [filteredConnections, memoryConnectorGroups]);
	const selectedConnectorKeys = useMemo(() => {
		const selectedConnectionIds = new Set(connectionFilterIds ?? []);
		return [
			...new Set([
				...(filters.platforms ?? []),
				...connectionLabelSources
					.filter((connection) => selectedConnectionIds.has(connection.id))
					.map((connection) => connection.connector_key),
			]),
		];
	}, [connectionFilterIds, connectionLabelSources, filters.platforms]);
	const selectedFeeds = useMemo(
		() =>
			workspaceFeeds.map((feed) => ({
				connectorKey: feed.connector_key,
				feedKey: feed.feed_key,
			})),
		[workspaceFeeds],
	);
	const eventKinds = useMemo(() => {
		if (
			(hasConnectionFilter && selectedConnectorKeys.length === 0) ||
			(hasFeedFilter && selectedFeeds.length === 0)
		) {
			return [];
		}

		return collectRelevantEventKinds({
			connectors: effectiveConnectorDefinitions,
			entityTypes: workspaceEntityTypes,
			selectedPlatforms: selectedConnectorKeys,
			selectedFeeds,
			selectedEntityTypes: filters.entityTypes,
		});
	}, [
		effectiveConnectorDefinitions,
		filters.entityTypes,
		hasConnectionFilter,
		hasFeedFilter,
		selectedConnectorKeys,
		selectedFeeds,
		workspaceEntityTypes,
	]);

	const connectionFilterLabel = useMemo(
		() =>
			hasConnectionFilter
				? resolveConnectionFilterLabel(
						connectionFilterIds ?? [],
						connectionLabelSources,
					)
				: null,
		[connectionFilterIds, connectionLabelSources, hasConnectionFilter],
	);
	const clientFilterIds = filters.clientIds;
	const hasClientFilter = (clientFilterIds?.length ?? 0) > 0;
	const { data: connectedClients = [] } = useConnectedClients(null, {
		enabled: isReady && canManageWorkspace && hasClientFilter,
	});
	const clientFilterGroups = useMemo(() => {
		if (!clientFilterIds) return [];
		const selected = new Set(clientFilterIds);
		return groupClients(connectedClients).filter((group) =>
			group.clientIds.some((id) => selected.has(id)),
		);
	}, [clientFilterIds, connectedClients]);
	const clientFilterLabel = useMemo(() => {
		if (!hasClientFilter || !clientFilterIds) return null;
		const titles = clientFilterGroups.map((group) => group.title);
		if (titles.length > 0) return `From ${titles.join(", ")}`;
		return `Filtered by client${clientFilterIds.length > 1 ? " registrations" : ""}`;
	}, [clientFilterGroups, clientFilterIds, hasClientFilter]);
	const clientFilterGroup =
		clientFilterGroups.length === 1 ? clientFilterGroups[0] : null;
	const clientFilterSourceLink =
		ownerSlug && clientFilterGroup
			? clientSourceLink(ownerSlug, clientFilterGroup.clientId)
			: undefined;

	// Conversation drill (Recent / app page deep-links): resolve the scoped
	// conversation's title so the banner reads like a place, not an id.
	const mcpActivityId = filters.mcpActivityId ?? null;
	const { data: mcpActivityScopes = [] } = useClientActivityScopes({
		enabled:
			isReady && canManageWorkspace && hasClientFilter && !!mcpActivityId,
		clientIds: clientFilterIds ?? [],
		limit: 100,
	});
	const mcpActivityLabel = useMemo(() => {
		if (!mcpActivityId) return null;
		const scope = mcpActivityScopes.find(
			(item) => item.activityId === mcpActivityId,
		);
		if (!scope) return "Selected conversation";
		const title = scope.title?.trim();
		if (title) return `Conversation “${title}”`;
		return scope.activityKind === "session"
			? "MCP session"
			: `Conversation ${scope.clientId}`;
	}, [mcpActivityId, mcpActivityScopes]);

	const feedFilterLabel = useMemo(
		() =>
			hasFeedFilter
				? resolveFeedFilterLabel(feedFilterIds ?? [], workspaceFeeds)
				: null,
		[feedFilterIds, hasFeedFilter, workspaceFeeds],
	);

	const agentFilterId = filters.agentId;
	const { data: workspaceAgents = [] } = useAgents({
		enabled: isReady && !!agentFilterId,
	});
	const agentFilterLabel = useMemo(() => {
		if (!agentFilterId || filters.behaviorId != null || scheduleScopeId) {
			return null;
		}
		if ((filters.platforms?.length ?? 0) > 0) return null;
		const agent = workspaceAgents.find(
			(item) => item.agentId === agentFilterId,
		);
		return agent ? `From agent ${agent.name}` : `From agent ${agentFilterId}`;
	}, [
		agentFilterId,
		filters.platforms,
		filters.behaviorId,
		scheduleScopeId,
		workspaceAgents,
	]);

	const behaviorFilterId = filters.behaviorId;
	const { data: scopedBehaviors = [] } = useAgentBehaviorsList(
		agentFilterId ?? undefined,
		{
			includeDetails: false,
		},
	);
	const behaviorFilterLabel = useMemo(() => {
		if (behaviorFilterId == null) return null;
		const match = scopedBehaviors.find(
			(w) => String(w.behavior_id) === String(behaviorFilterId),
		);
		return match
			? `From watch “${match.name}”`
			: `From Behavior #${behaviorFilterId}`;
	}, [scopedBehaviors, behaviorFilterId]);

	const { data: scopedSchedules = [] } = useSchedules(
		agentFilterId ?? undefined,
	);
	const scheduleFilterLabel = useMemo(() => {
		if (!scheduleScopeId || !agentFilterId) return null;
		const match = scopedSchedules.find((s) => s.id === scheduleScopeId);
		return match?.description?.trim()
			? `From schedule “${match.description.trim()}”`
			: "From scheduled task";
	}, [agentFilterId, scheduleScopeId, scopedSchedules]);

	const listenFilterLabel = useMemo(() => {
		if (
			!agentFilterId ||
			behaviorFilterId != null ||
			scheduleScopeId ||
			(filters.platforms?.length ?? 0) === 0
		) {
			return null;
		}
		const platform = filters.platforms?.[0];
		return platform ? `From ${platform} listen` : null;
	}, [agentFilterId, filters.platforms, scheduleScopeId, behaviorFilterId]);

	const drillSourceLinks = useMemo(() => {
		if (!ownerSlug) return {};
		const links: Record<string, DrillSourceLink | undefined> = {};

		if (hasFeedFilter && feedFilterIds?.length === 1) {
			const feed = workspaceFeeds.find((f) => f.id === feedFilterIds[0]);
			if (feed) links.feedIds = feedSourceLink(ownerSlug, feed);
		}

		if (hasConnectionFilter && connectionFilterIds?.length === 1) {
			const connection = connectionLabelSources.find(
				(c) => c.id === connectionFilterIds[0],
			);
			if (connection?.connector_key) {
				links.connectionIds = connectionSourceLink(ownerSlug, {
					id: connection.id,
					connector_key: connection.connector_key,
				});
			}
		}

		if (
			agentFilterId &&
			behaviorFilterId == null &&
			!scheduleScopeId &&
			(filters.platforms?.length ?? 0) === 0
		) {
			links.agentId = agentFeedsSourceLink(ownerSlug, agentFilterId);
		}

		if (agentFilterId && behaviorFilterId != null) {
			links.behaviorId = behaviorSourceLink(
				ownerSlug,
				String(behaviorFilterId),
			);
		}

		if (agentFilterId && scheduleScopeId) {
			links.schedule = scheduleSourceLink(
				ownerSlug,
				agentFilterId,
				scheduleScopeId,
			);
		}

		if (listenFilterLabel && agentFilterId) {
			links.listen = agentFeedsSourceLink(ownerSlug, agentFilterId);
		}

		return links;
	}, [
		agentFilterId,
		connectionFilterIds,
		connectionLabelSources,
		feedFilterIds,
		hasConnectionFilter,
		hasFeedFilter,
		filters.platforms,
		listenFilterLabel,
		ownerSlug,
		scheduleScopeId,
		behaviorFilterId,
		workspaceFeeds,
	]);

	// Classifiers only available when entity is specified
	const { data: classifiersData } = useEntityClassifiers(
		isReady && canManageWorkspace ? organizationId : null,
		isOrgWide ? undefined : effectiveEntityId,
	);
	const { data: publicClassifiersData } = usePublicEntityClassifiers(
		canReadPublicWorkspace && !isOrgWide ? ownerSlug : null,
		isOrgWide ? undefined : effectiveEntityId,
	);
	const effectiveClassifiersData = canManageWorkspace
		? classifiersData
		: publicClassifiersData;
	const classifierGroups = useMemo<BehaviorClassifierGroup[]>(() => {
		const groupMap = new Map<string, BehaviorClassifierGroup>();
		for (const c of effectiveClassifiersData || []) {
			const key = c.behavior_name ?? "__global__";
			if (!groupMap.has(key)) {
				groupMap.set(key, {
					behaviorName: c.behavior_name ?? null,
					classifiers: [],
				});
			}
			const group = groupMap.get(key)!;

			const attrValues = c.attribute_values || {};
			const values = Object.keys(attrValues);

			// Detect parent-child from attribute_values.parent field
			let parentSlug: string | null = null;
			const valuesByParentValue: Record<string, string[]> = {};

			for (const [val, config] of Object.entries(attrValues)) {
				if (config.parent) {
					for (const [pSlug, pValue] of Object.entries(config.parent)) {
						parentSlug = pSlug;
						if (!valuesByParentValue[pValue]) {
							valuesByParentValue[pValue] = [];
						}
						valuesByParentValue[pValue].push(val);
					}
				}
			}

			const existing = group.classifiers.find((gc) => gc.slug === c.slug);
			if (existing) {
				const merged = new Set([...existing.values, ...values]);
				existing.values = [...merged];
				for (const [pVal, cVals] of Object.entries(valuesByParentValue)) {
					if (!existing.valuesByParentValue[pVal]) {
						existing.valuesByParentValue[pVal] = [];
					}
					const mergedVals = new Set([
						...existing.valuesByParentValue[pVal],
						...cVals,
					]);
					existing.valuesByParentValue[pVal] = [...mergedVals];
				}
				if (parentSlug) existing.parentSlug = parentSlug;
			} else {
				group.classifiers.push({
					slug: c.slug,
					name: c.name,
					values,
					parentSlug,
					valuesByParentValue,
				});
			}
		}

		// Sort: parents first, then children
		for (const group of groupMap.values()) {
			group.classifiers.sort((a, b) => {
				if (a.parentSlug === null && b.parentSlug !== null) return -1;
				if (a.parentSlug !== null && b.parentSlug === null) return 1;
				return 0;
			});
		}

		return [...groupMap.values()];
	}, [effectiveClassifiersData]);

	const connectors = useMemo<ConnectorSelectorItem[]>(() => {
		const definitionsByKey = new Map(
			effectiveConnectorDefinitions.map((definition) => [
				definition.key,
				definition,
			]),
		);
		const seenKeys = new Set<string>(definitionsByKey.keys());

		return [...seenKeys]
			.map((key) => {
				const definition = definitionsByKey.get(key);
				return {
					key,
					name: definition?.name || key,
					description: definition?.description,
					icon: definition?.icon,
					faviconDomain: extractOAuthDomain(definition?.auth_schema),
				};
			})
			.sort((left, right) => left.name.localeCompare(right.name));
	}, [effectiveConnectorDefinitions]);

	// Fetch events with infinite scroll — gate by auth state so private orgs
	// don't issue spurious 404s against /public/knowledge/search. Also gate on
	// `isReady` so the transient (isAuthenticated=false, isReady=false) bootstrap
	// window doesn't fire the public query for an authenticated user.
	const authInfiniteQuery = useInfiniteContentWithFilters(
		isReady && canManageWorkspace ? organizationId : null,
		effectiveEntityId,
		filters,
		ownerSlug,
	);
	const publicInfiniteQuery = usePublicInfiniteContentWithFilters(
		canReadPublicWorkspace ? ownerSlug : null,
		effectiveEntityId,
		filters,
	);
	// While auth/membership is bootstrapping, both queries are disabled so either
	// side is empty; default to the auth side so the rendered query shape is
	// consistent.
	const infiniteQuery = canReadPublicWorkspace
		? publicInfiniteQuery
		: authInfiniteQuery;
	const {
		data: infiniteData,
		isLoading,
		error,
		fetchNextPage,
		hasNextPage,
		isFetchingNextPage,
	} = infiniteQuery;

	const contents = useMemo(
		() => infiniteData?.pages.flatMap((p) => p.content) ?? [],
		[infiniteData],
	);
	const firstPage = infiniteData?.pages[0];
	const total = firstPage?.total ?? 0;
	const classificationStats = firstPage?.classification_stats;
	// Drill-down banner label for the URL ?entity_id=… scope (only on the org-wide
	// Memory page; the entity tab gets its scope from the prop, no banner). The
	// name is read off the results since there's no entity-by-id lookup hook.
	const entityFilterLabel =
		filters.entityId != null
			? `Showing memory for ${contents[0]?.entity_name ?? "this entity"}`
			: null;
	const hasCursorInUrl = !!(
		filters.beforeOccurredAt || filters.afterOccurredAt
	);
	const useDateFeed = isDateFeedMode(filters);

	// Update URL with scroll position when new pages are loaded (date feed mode)
	const lastPage = infiniteData?.pages[infiniteData.pages.length - 1];
	const lastLoadedItem = lastPage?.content[lastPage.content.length - 1];
	useEffect(() => {
		if (!useDateFeed || !lastLoadedItem || infiniteData?.pages.length === 1)
			return;
		updateUrlFilters({
			beforeOccurredAt: lastLoadedItem.occurred_at,
			beforeId: lastLoadedItem.id,
		});
	}, [
		lastLoadedItem?.id,
		useDateFeed,
		updateUrlFilters,
		infiniteData?.pages.length,
		lastLoadedItem,
	]);

	const goToLatest = useCallback(() => {
		updateFilters({
			beforeOccurredAt: undefined,
			beforeId: undefined,
			afterOccurredAt: undefined,
			afterId: undefined,
		});
		window.scrollTo({ top: 0, behavior: "smooth" });
	}, [updateFilters]);

	// Infinite scroll sentinel
	const sentinelRef = useScrollSentinel({
		onIntersect: () => fetchNextPage(),
		enabled: !!hasNextPage && !isFetchingNextPage,
	});

	const [expandedBehaviorGroups, setExpandedBehaviorGroups] = useState<
		Set<string>
	>(new Set());
	const toggleBehaviorGroup = (key: string) => {
		const newSet = new Set(expandedBehaviorGroups);
		if (newSet.has(key)) {
			newSet.delete(key);
		} else {
			newSet.add(key);
		}
		setExpandedBehaviorGroups(newSet);
	};

	// Timeline rows: first collapse supersede chains (pending→executing→completed
	// become one head + history), then thread-group each head's replies. A chain
	// member folded into a head's history no longer opens its own row, so a run's
	// lifecycle reads as a single, followable node instead of N near-duplicates.
	const timelineRows = useMemo(() => {
		const collapsed = collapseSupersedeChains(contents);
		const heads = collapsed.map((c) => c.head);
		const collapsedByHeadId = new Map(collapsed.map((c) => [c.head.id, c]));
		const threadGroups = groupContentByThread(heads);
		return Array.from(threadGroups.entries()).map(([rootId, group]) => {
			const mainContent = group.root || group.replies[0];
			const node = mainContent
				? collapsedByHeadId.get(mainContent.id)
				: undefined;
			return {
				rootId,
				group,
				history: node?.history ?? [],
				runId: node?.runId ?? null,
			};
		});
	}, [contents]);
	const [expandedThreads, setExpandedThreads] = useState<Set<string>>(
		new Set(),
	);
	const [expandedHistory, setExpandedHistory] = useState<Set<string>>(
		new Set(),
	);
	const [showDeepReplies, setShowDeepReplies] = useState<Set<string>>(
		new Set(),
	);

	const toggleThread = (rootId: string) => {
		const newSet = new Set(expandedThreads);
		if (newSet.has(rootId)) {
			newSet.delete(rootId);
		} else {
			newSet.add(rootId);
		}
		setExpandedThreads(newSet);
	};

	const toggleHistory = (rootId: string) => {
		const newSet = new Set(expandedHistory);
		if (newSet.has(rootId)) {
			newSet.delete(rootId);
		} else {
			newSet.add(rootId);
		}
		setExpandedHistory(newSet);
	};

	const toggleDeepReplies = (rootId: string) => {
		const newSet = new Set(showDeepReplies);
		if (newSet.has(rootId)) {
			newSet.delete(rootId);
		} else {
			newSet.add(rootId);
		}
		setShowDeepReplies(newSet);
	};

	// Keep relative timestamps stable while the user is on the page.
	const sampleEvents = useMemo(() => buildSampleEvents(), []);

	// Handle date selection from timeline
	const handleTimelineSelect = (start: Date, end: Date) => {
		updateFilters({ dateRange: [start, end] });
	};

	// Classification filter toggle
	const handleClassificationToggle = (slug: string, value: string) => {
		const current = filters.classificationFilters || {};
		const values = current[slug] || [];
		const updated = values.includes(value)
			? values.filter((v) => v !== value)
			: [...values, value];

		const newFilters: ClassificationFilters = { ...current };
		if (updated.length > 0) {
			newFilters[slug] = updated;
		} else {
			delete newFilters[slug];
			// Clear child classifier filters when parent is fully deselected
			for (const group of classifierGroups) {
				for (const c of group.classifiers) {
					if (c.parentSlug === slug) {
						delete newFilters[c.slug];
					}
				}
			}
		}
		updateFilters({ classificationFilters: newFilters });
	};

	if (error) return <TabErrorState label="knowledge" />;

	// Auth still resolving — both data queries are disabled, but the filter
	// bar + count placeholder still render so the user sees the page chrome
	// from the first frame. Treated like any other in-flight data state
	// below so the same list-skeleton renders.
	const isAuthLoading = !isReady || (isAuthenticated && isOrgLoading);
	const isListLoading = isAuthLoading || isLoading;

	const isInitialEmptyState = !isListLoading && total === 0 && !hasFilters;

	const emptyStateDescription = isAuthenticated
		? canManageWorkspace
			? "Activity is the workspace's live feed — every message, email, file, and record a connector pulls in lands here as an event. Connect your data to start collecting."
			: "Activity is the workspace's live feed of connector events. Join this workspace to add connectors and collect knowledge here."
		: "No public knowledge items are available yet";
	const showEmptyStateAction = Boolean(canManageWorkspace && ownerSlug);

	return (
		<TooltipProvider>
			<div className="space-y-4">
				{/* Memory: filters stick to the top of the pane. `top-12` used to
				    clear the Events/Entities tab strip, which the sidebar replaced —
				    leaving a gap that started this page's content lower than every
				    sibling. Elsewhere: normal flow filter row. */}
				<div
					className={
						hideSourceFilter
							? "sticky top-0 z-10 -mx-4 space-y-3 bg-background px-4 pb-3 lg:-mx-6 lg:px-6"
							: undefined
					}
				>
					<EventsFilterBar
						filters={filters}
						onFiltersChange={updateFilters}
						connectors={connectors}
						eventKinds={eventKinds}
						searchQuery={searchQuery}
						onSearchChange={setSearchQuery}
						hideSourceFilter={hideSourceFilter}
						ownerSlug={ownerSlug}
					/>
				</div>

				{/* Drill-down filter banners (permalink / "View in memory" entrypoints). */}
				{(
					[
						{
							key: "contentIds",
							label: (ids: number[]) =>
								`Showing knowledge item #${ids.join(", #")}`,
							ids: filters.contentIds,
							clear: { contentIds: undefined },
						},
						{
							key: "windowId",
							label: (id: number) => `Filtered by Behavior window #${id}`,
							id: filters.windowId,
							clear: { windowId: undefined },
						},
						{
							key: "entityId",
							text: entityFilterLabel,
							clear: { entityId: undefined },
						},
						{
							key: "feedIds",
							text: feedFilterLabel,
							sourceLink: drillSourceLinks.feedIds,
							clear: { feedIds: undefined },
						},
						{
							key: "connectionIds",
							text: connectionFilterLabel,
							sourceLink: drillSourceLinks.connectionIds,
							clear: { connectionIds: undefined },
						},
						{
							key: "mcpActivityId",
							text: mcpActivityLabel,
							clear: { mcpActivityId: undefined },
						},
						{
							key: "clientIds",
							text: clientFilterLabel,
							sourceLink: clientFilterSourceLink,
							details:
								clientFilterIds && clientFilterIds.length > 0 ? (
									<ClientFilterDetails
										ownerSlug={ownerSlug}
										clientIds={clientFilterIds}
										linkedUser={clientFilterGroup?.linkedUser}
										linkedUserEntitySlug={
											clientFilterGroup?.linkedUserEntitySlug
										}
									/>
								) : undefined,
							clear: { clientIds: undefined },
						},
						{
							key: "behaviorId",
							text: behaviorFilterLabel,
							sourceLink: drillSourceLinks.behaviorId,
							clear: { behaviorId: undefined },
						},
						{
							key: "schedule",
							text: scheduleFilterLabel,
							sourceLink: drillSourceLinks.schedule,
							clear: { schedule: undefined, runIds: undefined },
						},
						{
							key: "listen",
							text: listenFilterLabel,
							sourceLink: drillSourceLinks.listen,
							clear: { platforms: undefined, connectionIds: undefined },
						},
						{
							key: "agentId",
							text: agentFilterLabel,
							sourceLink: drillSourceLinks.agentId,
							clear: {
								agentId: undefined,
								behaviorId: undefined,
								schedule: undefined,
								platforms: undefined,
							},
						},
						{
							key: "runIds",
							label: (ids: number[]) =>
								`Filtered by run${ids.length > 1 ? "s" : ""} #${ids.join(", #")}`,
							ids: filters.runIds,
							clear: { runIds: undefined, schedule: undefined },
						},
					] as const
				)
					.map((b) => {
						const text =
							"text" in b && b.text
								? b.text
								: "ids" in b && b.ids && b.ids.length > 0
									? b.label(b.ids as number[])
									: "id" in b && b.id != null
										? (b.label as (id: number) => string)(b.id as number)
										: null;
						if (!text) return null;
						return (
							<DrillFilterBanner
								key={b.key}
								text={text}
								sourceLink={"sourceLink" in b ? b.sourceLink : undefined}
								details={"details" in b ? b.details : undefined}
								onClear={() =>
									updateFilters(
										b.clear as PartialEventFilters & {
											schedule?: undefined;
										},
									)
								}
							/>
						);
					})
					.filter(Boolean)}

				{/* Timeline - only show when entity is specified */}
				{canManageWorkspace &&
					!isOrgWide &&
					effectiveEntityId &&
					organizationId && (
						<EventsTimeline
							entityId={effectiveEntityId}
							organizationId={organizationId}
							ownerSlug={ownerSlug || ""}
							selectedRange={filters.dateRange || undefined}
							onSelectRange={handleTimelineSelect}
						/>
					)}

				{classifierGroups.length > 0 && (
					<div className="space-y-2">
						{classifierGroups.map((group) => {
							const groupKey = group.behaviorName ?? "__global__";
							const hasActiveFilters = group.classifiers.some(
								(c) =>
									(filters.classificationFilters?.[c.slug]?.length || 0) > 0,
							);
							const isExpanded =
								expandedBehaviorGroups.has(groupKey) || hasActiveFilters;

							return (
								<Collapsible
									key={groupKey}
									open={isExpanded}
									onOpenChange={() => toggleBehaviorGroup(groupKey)}
								>
									<div className="flex items-center gap-1.5">
										<CollapsibleTrigger asChild>
											<Button variant="ghost" size="sm" className="h-6 w-6 p-0">
												{isExpanded ? (
													<ChevronDown className="h-3.5 w-3.5" />
												) : (
													<ChevronRight className="h-3.5 w-3.5" />
												)}
											</Button>
										</CollapsibleTrigger>
										{group.behaviorName && (
											<span className="text-sm font-medium text-muted-foreground">
												{group.behaviorName}
											</span>
										)}
									</div>
									<CollapsibleContent className="space-y-1.5 mt-1.5 ml-6">
										{group.classifiers
											.filter((classifier) => classifier.parentSlug === null)
											.map((classifier) => {
												const selectedValues =
													filters.classificationFilters?.[classifier.slug] ||
													[];
												const childClassifiers = group.classifiers.filter(
													(c) => c.parentSlug === classifier.slug,
												);

												return (
													<div key={classifier.slug}>
														<div className="flex flex-wrap items-center gap-1.5">
															<span className="text-sm font-medium text-muted-foreground shrink-0">
																{classifier.name}
															</span>
															{classifier.values.map((value) => {
																const isSelected =
																	selectedValues.includes(value);
																const count =
																	classificationStats?.[classifier.slug]?.[
																		value
																	];
																return (
																	<Badge
																		key={value}
																		variant={isSelected ? "default" : "outline"}
																		className="cursor-pointer"
																		onClick={() =>
																			handleClassificationToggle(
																				classifier.slug,
																				value,
																			)
																		}
																	>
																		{value}
																		{count != null && (
																			<span className="ml-1 opacity-60">
																				{count}
																			</span>
																		)}
																	</Badge>
																);
															})}
														</div>
														{selectedValues.length > 0 &&
															childClassifiers.map((child) => {
																const visibleValues = [
																	...new Set(
																		selectedValues.flatMap(
																			(pv) =>
																				child.valuesByParentValue[pv] || [],
																		),
																	),
																];
																if (visibleValues.length === 0) return null;
																return (
																	<div
																		key={child.slug}
																		className="flex flex-wrap items-center gap-1.5 ml-4 mt-1.5"
																	>
																		<span className="text-sm font-medium text-muted-foreground shrink-0">
																			{child.name}
																		</span>
																		{visibleValues.map((value) => {
																			const isSelected =
																				filters.classificationFilters?.[
																					child.slug
																				]?.includes(value);
																			const count =
																				classificationStats?.[child.slug]?.[
																					value
																				];
																			return (
																				<Badge
																					key={value}
																					variant={
																						isSelected ? "default" : "outline"
																					}
																					className="cursor-pointer"
																					onClick={() =>
																						handleClassificationToggle(
																							child.slug,
																							value,
																						)
																					}
																				>
																					{value}
																					{count != null && (
																						<span className="ml-1 opacity-60">
																							{count}
																						</span>
																					)}
																				</Badge>
																			);
																		})}
																	</div>
																);
															})}
													</div>
												);
											})}
									</CollapsibleContent>
								</Collapsible>
							);
						})}
					</div>
				)}

				{/* Back to latest + content count. Render a count-shaped skeleton
            during the loading window so the row reserves height — keeps the
            filter bar above and item list below from shifting when the
            count materializes. */}
				<div className="flex items-center justify-between pb-2 text-sm text-muted-foreground">
					{isListLoading ? (
						<Skeleton className="h-4 w-20" />
					) : total > 0 ? (
						<span>{`${total.toLocaleString()} items`}</span>
					) : (
						<span />
					)}
					{!isListLoading && total > 0 && hasCursorInUrl && (
						<Button
							variant="ghost"
							size="sm"
							className="h-7 gap-1"
							onClick={goToLatest}
						>
							<ArrowUp className="h-3.5 w-3.5" />
							Back to latest
						</Button>
					)}
				</div>

				{/* Feed list */}
				{isListLoading ? (
					<div className="space-y-4">
						{[
							"skeleton-1",
							"skeleton-2",
							"skeleton-3",
							"skeleton-4",
							"skeleton-5",
						].map((key) => (
							<Skeleton key={key} className="h-32 rounded-lg" />
						))}
					</div>
				) : isInitialEmptyState ? (
					/* Nothing collected yet: a sample feed under an overlay. The filter
					   bar and count row above are the page's real chrome — only this
					   region is substituted, so the user sees the page they're about to
					   fill rather than a substitute screen. */
					<div className="relative">
						<div
							aria-hidden="true"
							inert
							className="pointer-events-none select-none opacity-20 [mask-image:linear-gradient(to_bottom,black_70%,transparent)]"
						>
							<div className="pt-1">
								{sampleEvents.map((sample, index) => (
									<TimelineRow
										key={sample.id}
										occurredAt={sample.occurred_at}
										isLast={index === sampleEvents.length - 1}
									>
										<EventCard content={sample} />
									</TimelineRow>
								))}
							</div>
						</div>
						<div className="absolute inset-x-0 top-0 flex justify-center px-4 pt-10">
							<div className={cn(FILLED_BOX, "max-w-md px-6")}>
								<TabEmptyState
									icon={Inbox}
									title="No activity yet"
									description={emptyStateDescription}
									actionLabel={
										showEmptyStateAction ? "Connect your data" : undefined
									}
									onAction={
										showEmptyStateAction && ownerSlug
											? () =>
													void navigate({
														to: "/$owner/connectors",
														params: { owner: ownerSlug },
													})
											: undefined
									}
								/>
							</div>
						</div>
					</div>
				) : contents.length === 0 ? (
					<TabEmptyState
						icon={Inbox}
						title="No results found"
						description="Try adjusting your filters to find what you are looking for"
						actionLabel={hasFilters ? "Clear filters" : undefined}
						onAction={hasFilters ? clearFilters : undefined}
					/>
				) : (
					<div className="pt-1">
						{timelineRows.map(
							({ rootId, group, history, runId }, groupIndex, allRows) => {
								const hasReplies = group.replies.length > 0;
								const isExpanded = expandedThreads.has(rootId);
								const showingDeep = showDeepReplies.has(rootId);
								const historyOpen = expandedHistory.has(rootId);

								// Separate shallow (depth <= 3) and deep (depth > 3) replies
								const shallowReplies = group.replies.filter(
									(r) => r.depth <= 3,
								);
								const deepReplies = group.replies.filter((r) => r.depth > 3);

								// If no root, this is an orphaned reply thread
								const isOrphanedThread =
									!group.root && group.replies.length > 0;
								const mainContent = group.root || group.replies[0];

								if (!mainContent) return null;

								const isLastRow = groupIndex === allRows.length - 1;

								return (
									<TimelineRow
										key={rootId}
										occurredAt={mainContent.occurred_at}
										isLast={isLastRow}
									>
										{/* Entity link in org-wide mode */}
										{isOrgWide && ownerSlug && mainContent.entity_name && (
											<div className="mb-2">
												<EntityLinkCell
													ownerSlug={ownerSlug}
													entity={{
														entityId: mainContent.entity_ids?.[0],
														entityName: mainContent.entity_name,
														entityType: mainContent.entity_type || "brand",
														entitySlug: mainContent.entity_slug || "",
													}}
													tab="events"
												/>
											</div>
										)}

										{/* Main event card */}
										<EventCard
											content={mainContent}
											showParentContext={
												isOrphanedThread && !!mainContent.parent_context
											}
										/>

										{/* Earlier states — for a run, its lifecycle (pending →
									    executing → completed) plus the "needs approval"
									    notification, all folded here and labelled by run so the
									    node reads as one run's history. Collapsed by default. */}
										{history.length > 0 && (
											<Collapsible open={historyOpen}>
												<CollapsibleTrigger asChild>
													<Button
														variant="ghost"
														size="sm"
														className="mt-1 h-7 gap-1 text-xs text-muted-foreground"
														onClick={() => toggleHistory(rootId)}
													>
														<History className="h-3.5 w-3.5" />
														{historyOpen ? (
															<>
																<ChevronUp className="h-3.5 w-3.5" />
																Hide {runId != null ? `run #${runId} ` : ""}
																history
															</>
														) : (
															<>
																<ChevronDown className="h-3.5 w-3.5" />
																{runId != null
																	? `Run #${runId} · ${
																			history.length === 1
																				? "1 earlier step"
																				: `${history.length} earlier steps`
																		}`
																	: history.length === 1
																		? "1 earlier state"
																		: `${history.length} earlier states`}
															</>
														)}
													</Button>
												</CollapsibleTrigger>
												<CollapsibleContent className="mt-2 space-y-3 border-l-2 border-l-muted pl-4">
													{history.map((prev) => (
														<div key={prev.id}>
															<time
																dateTime={new Date(
																	prev.occurred_at,
																).toISOString()}
																title={formatShortDate(prev.occurred_at)}
																className="mb-1 block text-xs text-muted-foreground"
															>
																{formatTimeAgo(prev.occurred_at)}
															</time>
															<EventCard content={prev} />
														</div>
													))}
												</CollapsibleContent>
											</Collapsible>
										)}

										{/* Thread replies */}
										{hasReplies && (
											<Collapsible open={isExpanded}>
												<CollapsibleTrigger asChild>
													<Button
														variant="ghost"
														size="sm"
														className="mt-2 ml-6 gap-1"
														onClick={() => toggleThread(rootId)}
													>
														<MessageSquare className="h-3.5 w-3.5" />
														{isExpanded ? (
															<>
																<ChevronUp className="h-3.5 w-3.5" />
																Hide {group.replies.length} replies
															</>
														) : (
															<>
																<ChevronDown className="h-3.5 w-3.5" />
																Show {group.replies.length} replies
															</>
														)}
													</Button>
												</CollapsibleTrigger>
												<CollapsibleContent className="space-y-2 mt-2">
													{/* Shallow replies */}
													{shallowReplies.map((reply) => (
														<EventCard key={reply.id} content={reply} isReply />
													))}

													{/* Deep replies toggle */}
													{deepReplies.length > 0 && (
														<>
															<Button
																variant="ghost"
																size="sm"
																className="ml-12"
																onClick={() => toggleDeepReplies(rootId)}
															>
																{showingDeep ? (
																	<>Hide {deepReplies.length} nested replies</>
																) : (
																	<>Show {deepReplies.length} nested replies</>
																)}
															</Button>
															{showingDeep &&
																deepReplies.map((reply) => (
																	<EventCard
																		key={reply.id}
																		content={reply}
																		isReply
																	/>
																))}
														</>
													)}
												</CollapsibleContent>
											</Collapsible>
										)}
									</TimelineRow>
								);
							},
						)}
					</div>
				)}

				{/* Infinite scroll sentinel */}
				<div ref={sentinelRef} className="h-1" />
				{isFetchingNextPage && (
					<div className="flex justify-center py-4">
						<Spinner size="xl" className="text-muted-foreground" />
					</div>
				)}
			</div>
		</TooltipProvider>
	);
}

// Content types — canonical definition lives in @lobu/connector-sdk
import type { ContentItem } from '@lobu/connector-sdk';
import { useInfiniteQuery, useQuery } from '@tanstack/react-query';
import { getFilterIdentity } from '@/components/entity-tabs/events-tab/navigation';
import type { PartialEventFilters } from '../event-filters';
import { convertFiltersToApiParams, isDateFeedMode } from '../event-filters';
import {
  API_URL,
  apiCall,
  apiErrorFor,
  fetchWithTimeout,
  normalizeOrgContext,
  resolveApiScope,
  resolveOrgSelector,
} from './core';
import { createQuery } from './hook-factory';

export type { ContentItem };

interface ExtendedContentListResult {
  content: ContentItem[];
  total: number;
  classification_stats?: Record<string, Record<string, number>>;
  timeline?: Array<{ date: string; count: number }>;
  page: {
    limit: number;
    offset: number;
    has_more: boolean;
    has_older?: boolean;
    has_newer?: boolean;
  };
}

function appendQueryParam(params: URLSearchParams, key: string, value: unknown) {
  if (value === undefined || value === null) return;
  if (Array.isArray(value)) {
    if (value.length === 0) return;
    params.set(key, value.join(','));
    return;
  }
  if (typeof value === 'object') {
    params.set(key, JSON.stringify(value));
    return;
  }
  params.set(key, String(value));
}

// ============================================================
// Infinite scroll content queries
// ============================================================

const PAGE_SIZE = 50;

type InfinitePageParam = null | {
  before_occurred_at?: string;
  before_id?: number;
  offset?: number;
};

function getNextPageParam(
  lastPage: ExtendedContentListResult,
  isDateFeed: boolean
): InfinitePageParam | undefined {
  if (isDateFeed) {
    if (!lastPage.page.has_older) return undefined;
    const lastItem = lastPage.content[lastPage.content.length - 1];
    if (!lastItem?.occurred_at) return undefined;
    return { before_occurred_at: lastItem.occurred_at, before_id: lastItem.id };
  }
  if (!lastPage.page.has_more) return undefined;
  return { offset: lastPage.page.offset + lastPage.page.limit };
}

function buildInfiniteApiParams(
  baseFilters: PartialEventFilters,
  entityId: number | undefined,
  pageParam: InfinitePageParam
): Record<string, unknown> {
  const filtersForApi: PartialEventFilters = { ...baseFilters };
  // Strip any cursor/page from base filters — we use pageParam instead
  delete filtersForApi.page;
  delete filtersForApi.beforeOccurredAt;
  delete filtersForApi.beforeId;
  delete filtersForApi.afterOccurredAt;
  delete filtersForApi.afterId;

  if (pageParam) {
    if (pageParam.before_occurred_at != null && pageParam.before_id != null) {
      filtersForApi.beforeOccurredAt = pageParam.before_occurred_at;
      filtersForApi.beforeId = pageParam.before_id;
    }
  }

  const offset = pageParam?.offset;
  return convertFiltersToApiParams(filtersForApi, entityId, {
    limit: PAGE_SIZE,
    ...(offset != null ? { offset } : {}),
  });
}

export function useInfiniteContentWithFilters(
  organizationId?: string | null,
  entityId?: number,
  filters?: PartialEventFilters,
  orgSlug?: string
) {
  const ctx = normalizeOrgContext(orgSlug ? { slug: orgSlug } : undefined);
  const hasContext = !!(ctx.organizationId || ctx.slug);
  const isDateFeed = filters ? isDateFeedMode(filters) : false;
  const filterIdentity = filters ? getFilterIdentity(filters) : null;

  return useInfiniteQuery({
    queryKey: ['contents-infinite', ctx.organizationId, ctx.slug, entityId, filterIdentity],
    queryFn: async ({ pageParam }) => {
      const params = buildInfiniteApiParams(filters ?? {}, entityId, pageParam);
      return apiCall<ExtendedContentListResult>(
        'read_knowledge',
        { ...params, include_classification: 'summary' },
        resolveOrgSelector(ctx)
      );
    },
    initialPageParam: null as InfinitePageParam,
    getNextPageParam: (lastPage) => getNextPageParam(lastPage, isDateFeed),
    enabled: !!organizationId && !!filters && hasContext,
    staleTime: 30000,
  });
}

export function usePublicInfiniteContentWithFilters(
  orgSlug?: string | null,
  entityId?: number,
  filters?: PartialEventFilters
) {
  const isDateFeed = filters ? isDateFeedMode(filters) : false;
  const filterIdentity = filters ? getFilterIdentity(filters) : null;

  return useInfiniteQuery({
    queryKey: ['public-contents-infinite', orgSlug, entityId, filterIdentity],
    queryFn: async ({ pageParam }) => {
      const scope = resolveApiScope({ slug: orgSlug ?? null });
      const params = buildInfiniteApiParams(filters ?? {}, entityId, pageParam);
      const searchParams = new URLSearchParams();
      for (const [key, value] of Object.entries(params)) {
        appendQueryParam(searchParams, key, value);
      }

      const response = await fetchWithTimeout(
        `${API_URL}/api/${scope.slug}/public/knowledge/search?${searchParams.toString()}`,
        { credentials: 'include' }
      );
      if (!response.ok) throw await apiErrorFor(response);
      return (await response.json()) as ExtendedContentListResult;
    },
    initialPageParam: null as InfinitePageParam,
    getNextPageParam: (lastPage) => getNextPageParam(lastPage, isDateFeed),
    enabled: !!orgSlug && !!filters,
    staleTime: 30000,
  });
}

// ============================================================
// Content Distribution (Timeline)
// ============================================================

interface ContentDistributionResult {
  distribution: Array<{ date: string; count: number; platform?: string }>;
}

export function useContentDistribution(
  organizationId?: string | null,
  options?: {
    entityId?: number;
    connectionIds?: number[];
    groupByPlatform?: boolean;
  },
  orgContext?: string | { slug?: string | null }
) {
  return useQuery({
    queryKey: [
      'content-distribution',
      organizationId,
      options?.entityId,
      options?.connectionIds,
      options?.groupByPlatform,
      typeof orgContext === 'string' ? orgContext : orgContext?.slug,
    ],
    queryFn: async () => {
      const params = new URLSearchParams();
      if (options?.connectionIds && options.connectionIds.length > 0) {
        params.append('connection_ids', options.connectionIds.join(','));
      }
      if (options?.groupByPlatform) {
        params.append('group_by_platform', 'true');
      }
      const queryString = params.toString();
      const scope = resolveApiScope(orgContext);
      const url = `${API_URL}/api/${scope.slug}/entities/${options?.entityId}/content-distribution${queryString ? `?${queryString}` : ''}`;

      const response = await fetchWithTimeout(url, {
        method: 'GET',
        credentials: 'include',
      });

      if (!response.ok) {
        throw await apiErrorFor(response);
      }

      const result: ContentDistributionResult = await response.json();
      return result.distribution || [];
    },
    enabled: !!organizationId && !!options?.entityId,
    staleTime: 60000,
  });
}

// ============================================================
// Classifiers
// ============================================================

export interface Classifier {
  id: number;
  slug: string;
  name: string;
  description?: string;
  attribute_key: string;
  current_version: number;
  min_similarity: number;
  fallback_value?: string;
  attribute_values: Record<
    string,
    { description?: string; examples?: string[]; parent?: Record<string, string> }
  >;
  is_inherited?: boolean;
  behavior_id?: number | null;
  behavior_name?: string | null;
}

interface ClassifiersResult {
  classifiers: Classifier[];
}

export const useEntityClassifiers = createQuery<
  [organizationId?: string | null, entityId?: number],
  Classifier[]
>({
  queryKey: (organizationId, entityId) => ['classifiers', organizationId, entityId],
  tool: 'manage_classifiers',
  body: (_organizationId, entityId) => ({
    action: 'list',
    entity_id: entityId,
  }),
  transform: (r) => r.data?.classifiers || [],
  enabled: (organizationId, entityId) => !!organizationId && !!entityId,
  staleTime: 60000,
});

export function usePublicEntityClassifiers(orgSlug?: string | null, entityId?: number) {
  return useQuery({
    queryKey: ['public-classifiers', orgSlug, entityId],
    queryFn: async () => {
      const scope = resolveApiScope({ slug: orgSlug ?? null });
      const params = new URLSearchParams();
      if (entityId) params.set('entity_id', String(entityId));

      const response = await fetchWithTimeout(
        `${API_URL}/api/${scope.slug}/public/classifiers${params.toString() ? `?${params}` : ''}`,
        {
          credentials: 'include',
        }
      );
      if (!response.ok) {
        throw await apiErrorFor(response);
      }
      const result = (await response.json()) as ClassifiersResult & {
        data?: { classifiers?: Classifier[] };
      };
      return result.data?.classifiers ?? [];
    },
    enabled: !!orgSlug && !!entityId,
    staleTime: 60000,
  });
}

