export function applyEventTabDefaults(
	filters: PartialEventFilters,
): PartialEventFilters {
	return {
		sortBy: filters.sortBy ?? "date",
		sortOrder: filters.sortOrder ?? "desc",
		...filters,
	};
}

export function isDateFeedMode(filters: PartialEventFilters): boolean {
	const resolved = applyEventTabDefaults(filters);
	return resolved.sortBy === "date" && resolved.sortOrder === "desc";
}

export function hasActiveFilters(filters: PartialEventFilters): boolean {
	return (
		(filters.searchQuery?.trim() ?? "").length > 0 ||
		(filters.platforms?.length ?? 0) > 0 ||
		(filters.dateRange !== null && filters.dateRange !== undefined) ||
		(filters.engagementRange?.[0] ?? 0) !== 0 ||
		(filters.engagementRange?.[1] ?? 100) !== 100 ||
		(filters.reviewStatus ?? "all") !== "all" ||
		(filters.semanticTypes?.length ?? 0) > 0 ||
		Object.keys(filters.classificationFilters ?? {}).length > 0 ||
		filters.windowId != null ||
		filters.entityId != null ||
		(filters.contentIds != null && filters.contentIds.length > 0) ||
		(filters.connectionIds != null && filters.connectionIds.length > 0) ||
		(filters.feedIds != null && filters.feedIds.length > 0) ||
		(filters.runIds != null && filters.runIds.length > 0) ||
		(filters.agentId != null && filters.agentId !== "") ||
		(filters.clientIds != null && filters.clientIds.length > 0) ||
		(filters.mcpActivityId != null && filters.mcpActivityId !== "") ||
		filters.behaviorId != null ||
		(filters.interactionStatus != null && filters.interactionStatus !== "")
	);
}

import type { ContentItem } from "@/lib/api";
import {
	applyEventTabDefaults,
	type PartialEventFilters,
} from "@/lib/event-filters";

const SCROLL_POSITION_KEYS = new Set([
	"page",
	"beforeOccurredAt",
	"beforeId",
	"afterOccurredAt",
	"afterId",
]);

/** Returns a stable identity for filters excluding scroll-position params. */
export function getFilterIdentity(
	filters: PartialEventFilters,
): Omit<
	PartialEventFilters,
	"page" | "beforeOccurredAt" | "beforeId" | "afterOccurredAt" | "afterId"
> {
	const {
		page,
		beforeOccurredAt,
		beforeId,
		afterOccurredAt,
		afterId,
		...rest
	} = filters;
	return rest;
}

export function mergeEventTabFilters(
	current: PartialEventFilters,
	updates: Partial<PartialEventFilters>,
): PartialEventFilters {
	const merged = {
		...applyEventTabDefaults(current),
		...updates,
	};
	const changedKeys = Object.keys(updates);
	const scrollOnly =
		changedKeys.length > 0 &&
		changedKeys.every((key) => SCROLL_POSITION_KEYS.has(key));

	if (!scrollOnly) {
		merged.beforeOccurredAt = undefined;
		merged.beforeId = undefined;
		merged.afterOccurredAt = undefined;
		merged.afterId = undefined;
		return merged;
	}

	if ("beforeOccurredAt" in updates || "beforeId" in updates) {
		merged.afterOccurredAt = undefined;
		merged.afterId = undefined;
	}

	if ("afterOccurredAt" in updates || "afterId" in updates) {
		merged.beforeOccurredAt = undefined;
		merged.beforeId = undefined;
	}

	return merged;
}

export function getThreadGroupKey(
	item: Pick<ContentItem, "id" | "origin_id" | "root_origin_id">,
): string {
	return item.root_origin_id || item.origin_id || String(item.id);
}

/**
 * An event plus the earlier states it superseded, newest-first. When an action
 * runs (pending → executing → completed) the append-only log emits one row per
 * state, each linked to the prior via `supersedes_event_id`. Rendering all of
 * them as sibling timeline nodes buries the *current* state in near-duplicate
 * rows, so we collapse the chain to its head (the latest, un-superseded state)
 * and hang the predecessors off `history` for an on-demand "how it got here".
 */
export interface CollapsedItem {
	/** The latest state in the chain — what the timeline node renders. */
	head: ContentItem;
	/** Earlier superseded states, newest-first; empty for a plain event. */
	history: ContentItem[];
	/**
	 * The run this node belongs to, when its events originated from one. Set for
	 * operation chains and their satellite events (the "needs approval"
	 * notification); null for plain content. Used to surface a "Run #N" identity
	 * and to fold same-run satellites into one node.
	 */
	runId: number | null;
}

/** True when this event is an operation/approval state (has a real status). */
function isOperationState(item: ContentItem): boolean {
	return (
		item.interaction_type === "approval" ||
		item.semantic_type === "operation" ||
		item.interaction_status != null
	);
}

/**
 * Collapse supersede chains within a page of content, then fold same-run
 * satellite events into their run's node.
 *
 * Two passes:
 *  1. Supersede collapse — items linked by `supersedes_event_id` (child → the id
 *     it replaced) fold to their head (latest, un-superseded state), with
 *     predecessors hung off `history` newest-first. Only chains fully present in
 *     `contents` collapse; a predecessor that paginated onto another page stays
 *     standalone, so nothing is hidden.
 *  2. Run fold — a run emits more than its operation chain: the "needs approval"
 *     notification is a separate event sharing the run's `run_id` but *not* the
 *     supersede chain. Rendering it as its own node duplicates the run on the
 *     timeline. So we fold each run's satellite events into the run's node (the
 *     one whose head is the operation state), pushing them into `history`.
 *
 * Order and identity of surviving heads are preserved.
 */
export function collapseSupersedeChains(
	contents: ContentItem[],
): CollapsedItem[] {
	const byId = new Map<number, ContentItem>();
	for (const item of contents) byId.set(item.id, item);

	// An event is superseded (not a head) iff some other in-page item points at
	// it via supersedes_event_id.
	const supersededIds = new Set<number>();
	for (const item of contents) {
		if (item.supersedes_event_id != null && byId.has(item.supersedes_event_id)) {
			supersededIds.add(item.supersedes_event_id);
		}
	}

	const collapsed: CollapsedItem[] = [];
	for (const item of contents) {
		if (supersededIds.has(item.id)) continue; // folded into its successor's history

		// Walk backwards from this head down the supersedes links, collecting the
		// earlier states that are present in this page.
		const history: ContentItem[] = [];
		let cursor = item.supersedes_event_id;
		const guard = new Set<number>([item.id]); // cycle guard for malformed chains
		while (cursor != null && byId.has(cursor) && !guard.has(cursor)) {
			const prev = byId.get(cursor)!;
			history.push(prev);
			guard.add(cursor);
			cursor = prev.supersedes_event_id;
		}

		collapsed.push({ head: item, history, runId: item.run_id ?? null });
	}

	// Pass 2 — fold same-run satellites into the run's operation node. A run's
	// node is the collapsed item whose head is the operation state; every other
	// same-run collapsed item (the notification) folds into it. If a run has no
	// operation state on the page (only a notification survived), the satellite
	// stays standalone rather than vanishing.
	const opNodeIndexByRun = new Map<number, number>();
	collapsed.forEach((node, index) => {
		if (node.runId != null && isOperationState(node.head)) {
			// First operation node wins the run (there is normally exactly one head
			// per run after supersede collapse).
			if (!opNodeIndexByRun.has(node.runId)) {
				opNodeIndexByRun.set(node.runId, index);
			}
		}
	});

	const foldedInto = new Set<number>(); // indices absorbed as satellites
	collapsed.forEach((node, index) => {
		if (node.runId == null || isOperationState(node.head)) return;
		const targetIndex = opNodeIndexByRun.get(node.runId);
		if (targetIndex == null || targetIndex === index) return;
		// Append the satellite (e.g. the approval notification) plus any of its own
		// history into the run node's history, then drop it as a top-level node.
		const target = collapsed[targetIndex];
		target.history.push(node.head, ...node.history);
		foldedInto.add(index);
	});

	return collapsed.filter((_, index) => !foldedInto.has(index));
}

export interface ThreadGroup {
	root: ContentItem | null;
	replies: ContentItem[];
	hasParentContext: boolean;
}

export function groupContentByThread(
	contents: ContentItem[],
): Map<string, ThreadGroup> {
	const groups = new Map<string, ThreadGroup>();

	for (const item of contents) {
		const rootId = getThreadGroupKey(item);
		if (!groups.has(rootId)) {
			groups.set(rootId, { root: null, replies: [], hasParentContext: false });
		}

		const group = groups.get(rootId);
		if (!group) {
			continue;
		}

		if (item.depth === 0) {
			group.root = item;
			group.hasParentContext = !!item.parent_context;
		} else {
			group.replies.push(item);
		}
	}

	return groups;
}

