import { useEffect, useMemo, useRef, useState } from "react";
import { Spinner } from "@/components/ui/spinner";
import { type RunScope, useInfiniteRuns } from "@/lib/api";
import { bucketRunTypes, RunsFilterBar } from "./runs-filter-bar";
import { RunsRowsSkeleton } from "./runs-loading-shell";
import { RunsTable, type RunsTableColumns } from "./runs-table";

/**
 * Runs surface for connection, connector, device, and feed scopes: a run-type
 * bucket + status filter over an infinite-scrolling table. Filter state is
 * local (not URL-persisted) so it stays decoupled from each route's search
 * schema. The table area gates on its own loading state — it never flashes the
 * empty state before the first page lands.
 */
export function RunsPanel({
	scope,
	ownerSlug,
}: {
	scope: RunScope;
	ownerSlug: string;
}) {
	const [bucket, setBucket] = useState("all");
	const [status, setStatus] = useState("all");

	const filters = useMemo(
		() => ({
			runTypes: bucketRunTypes(bucket),
			status: status === "all" ? undefined : status,
		}),
		[bucket, status],
	);

	const {
		data,
		isLoading,
		isError,
		hasNextPage,
		isFetchingNextPage,
		fetchNextPage,
	} = useInfiniteRuns(scope, filters, ownerSlug);

	const runs = useMemo(() => data?.pages.flatMap((p) => p.runs) ?? [], [data]);

	// Context columns: multi-feed scopes want a feed column; multi-connection
	// scopes (device + connector) want a connection column. Run-type only when
	// the "All" bucket mixes types.
	const columns: RunsTableColumns = {
		runType: bucket === "all",
		feed: true,
		connection: "deviceId" in scope || "connectorKey" in scope,
	};

	const sentinelRef = useRef<HTMLDivElement | null>(null);
	useEffect(() => {
		const el = sentinelRef.current;
		if (!el || !hasNextPage) return;
		const observer = new IntersectionObserver(
			(entries) => {
				if (entries[0]?.isIntersecting && !isFetchingNextPage) {
					void fetchNextPage();
				}
			},
			{ rootMargin: "200px" },
		);
		observer.observe(el);
		return () => observer.disconnect();
	}, [hasNextPage, isFetchingNextPage, fetchNextPage]);

	return (
		<div className="space-y-3">
			<RunsFilterBar
				bucket={bucket}
				status={status}
				onBucketChange={setBucket}
				onStatusChange={setStatus}
			/>
			{isLoading ? (
				<RunsRowsSkeleton />
			) : isError ? (
				<p className="rounded-lg border bg-destructive/5 px-3 py-6 text-center text-xs text-destructive">
					Failed to load runs.
				</p>
			) : runs.length === 0 ? (
				<p className="rounded-lg border bg-muted/20 px-3 py-6 text-center text-xs text-muted-foreground">
					No runs yet.
				</p>
			) : (
				<>
					<RunsTable runs={runs} ownerSlug={ownerSlug} columns={columns} />
					<div ref={sentinelRef} className="h-1" />
					{isFetchingNextPage && (
						<div className="flex justify-center py-3">
							<Spinner size="lg" className="text-muted-foreground" />
						</div>
					)}
				</>
			)}
		</div>
	);
}

