import { createFileRoute } from "@tanstack/react-router";
import { ActivityPane } from "@/components/activity/activity-pane";
import { MemoryConnectorGroupsProvider } from "@/components/memory/memory-connector-groups";
import { OwnerWorkspaceGate } from "@/components/owner-workspace-gate";
import { useWorkspaceRoot } from "@/lib/api";
import {
	parseAgentScope,
	parseEntityScope,
	parseScheduleScope,
	parseBehaviorScope,
} from "@/lib/memory-browse";
import { pruneSearch } from "@/lib/router-search";
import { decodeEntityTypeParam } from "@/lib/url";

/**
 * Activity: the org-wide Events stream ("what happened"). Entity browsing
 * ("what we know") lives on `/memory`; legacy `/memory?view=events` links
 * redirect here.
 */
export const Route = createFileRoute("/$owner/activity")({
	loader: ({ context: { queryClient }, params }) => {
		void queryClient.prefetchQuery(
			useWorkspaceRoot.queryOptions(params.owner, { slug: params.owner }),
		);
	},
	component: ActivityPage,
	validateSearch: (search: Record<string, unknown>) =>
		pruneSearch(search) as Record<string, string | undefined>,
});

function ActivityPage() {
	const { owner } = Route.useParams();
	const search = Route.useSearch();
	const typeScope =
		typeof search.type === "string" && search.type.trim()
			? decodeEntityTypeParam(search.type.trim())
			: undefined;
	const entityScope = parseEntityScope(search);
	const agentScope = parseAgentScope(search);
	const behaviorScope = parseBehaviorScope(search);
	const scheduleScope = parseScheduleScope(search);
	const attentionLens = search.lens === "attention";

	return (
		<div className="flex flex-1 flex-col gap-6 px-4 py-6 lg:px-6">
			<OwnerWorkspaceGate owner={owner}>
				{(props) => (
					<MemoryConnectorGroupsProvider
						organizationId={props.organizationId}
						isWorkspaceLoading={props.isWorkspaceLoading}
					>
						<div className="mx-auto flex min-h-0 w-full min-w-0 max-w-3xl flex-1 flex-col">
							<ActivityPane
								organizationId={props.organizationId}
								ownerSlug={props.ownerSlug}
								typeScope={typeScope}
								entityScope={entityScope}
								agentScope={agentScope}
								behaviorScope={behaviorScope}
								scheduleScope={scheduleScope}
								attentionLens={attentionLens}
							/>
						</div>
					</MemoryConnectorGroupsProvider>
				)}
			</OwnerWorkspaceGate>
		</div>
	);
}

import { Link } from "@tanstack/react-router";
import { Boxes, ChevronRight, X } from "lucide-react";
import type { ReactNode } from "react";
import { EventsTab } from "@/components/entity-tabs/events-tab";
import { TabEmptyState } from "@/components/entity-tabs/tab-states";
import {
	AttentionBulkBar,
	AttentionList,
	useAttentionInbox,
} from "./attention-inbox";
import { MemberScopeGate } from "@/components/memory/member-scope-gate";
import { Button } from "@/components/ui/button";
import { EntityIcon } from "@/components/ui/entity-icon";
import { useOrgContext } from "@/hooks/use-org-context";
import { useAgentBehaviorsList } from "@/hooks/use-behaviors";
import { useAgents, useEntityType, useResolvedPath } from "@/lib/api";
import { useSchedules } from "@/lib/api/schedules";
import { decodeEntityBrowsePath, decodeEntityTypeParam } from "@/lib/url";
import { cn } from "@/lib/utils";

/**
 * Activity content pane: the org-wide Events stream plus its scope drill-downs
 * (entity, agent → behavior/schedule). Additive event filters live in the
 * Events toolbar; this pane only resolves URL scopes and renders the header.
 */
export function ActivityPane({
	organizationId,
	ownerSlug,
	typeScope,
	entityScope,
	agentScope,
	behaviorScope,
	scheduleScope,
	attentionLens = false,
}: {
	organizationId: string | null;
	ownerSlug: string;
	typeScope?: string;
	entityScope?: string;
	agentScope?: string;
	behaviorScope?: string;
	scheduleScope?: string;
	/** The "Needs attention" lens: the workspace attention inbox instead of the
	 *  events stream. One Activity surface, two lenses. */
	attentionLens?: boolean;
}) {
	const { orgContext } = useOrgContext();
	// Same query (thus same cache entry) the attention list itself runs — the
	// lens badge costs no extra fetch.
	const { attentionItems } = useAttentionInbox(ownerSlug);
	const attentionCount = attentionItems.length;
	const lensToggle = (
		<div className="flex flex-wrap items-center justify-between gap-2">
			<div className="flex items-center gap-1.5">
				<Link
					to="/$owner/activity"
					params={{ owner: ownerSlug }}
					search={(prev) => ({ ...(prev ?? {}), lens: undefined })}
					aria-current={!attentionLens ? "page" : undefined}
					className={cn(
						"rounded-md px-2.5 py-1 text-xs font-medium transition-colors",
						!attentionLens
							? "bg-muted text-foreground"
							: "text-muted-foreground hover:text-foreground",
					)}
				>
					All activity
				</Link>
				<Link
					to="/$owner/activity"
					params={{ owner: ownerSlug }}
					search={(prev) => ({ ...(prev ?? {}), lens: "attention" })}
					aria-current={attentionLens ? "page" : undefined}
					className={cn(
						"flex items-center gap-1.5 rounded-md px-2.5 py-1 text-xs font-medium transition-colors",
						attentionLens
							? "bg-muted text-foreground"
							: "text-muted-foreground hover:text-foreground",
					)}
				>
					Needs attention
					{attentionCount > 0 ? (
						<span
							aria-label={`${attentionCount} item${attentionCount === 1 ? "" : "s"} need attention`}
							className="rounded-full bg-blue-500/15 px-1.5 py-0.5 text-[10px] font-semibold text-blue-600 dark:text-blue-400"
						>
							{attentionCount}
						</span>
					) : null}
				</Link>
			</div>
		</div>
	);
	const { data: agents = [] } = useAgents();
	const agentLabel = agentScope
		? (agents.find((agent) => agent.agentId === agentScope)?.name ?? agentScope)
		: undefined;
	const { data: agentBehaviors = [] } = useAgentBehaviorsList(agentScope, {
		includeDetails: false,
	});
	const behaviorLabel = behaviorScope
		? (agentBehaviors.find((w) => w.behavior_id === behaviorScope)?.name ??
			`Behavior ${behaviorScope}`)
		: undefined;
	const { data: agentSchedules = [] } = useSchedules(agentScope);
	const scheduleLabel = scheduleScope
		? (agentSchedules.find((s) => s.id === scheduleScope)?.description ??
			"Schedule")
		: undefined;
	const typeSlug = typeScope ? decodeEntityTypeParam(typeScope) : undefined;
	const isMemberScope =
		typeSlug === "$member" || entityScope?.split("/")[0] === "$member";

	// Resolve the selected entity (if any) to its id, for the events filters.
	const {
		data: resolved,
		isLoading: entityLoading,
		error: entityError,
	} = useResolvedPath(
		entityScope ? `/${ownerSlug}/${decodeEntityBrowsePath(entityScope)}` : "",
		orgContext,
	);
	const entity = entityScope ? resolved?.entity : undefined;
	// The `?entity=` scope points at nothing (deleted / bad slug): the resolve
	// settled with no entity and no in-flight fetch.
	const entityNotFound =
		entityScope != null &&
		!entityLoading &&
		(entityError != null || resolved?.entity == null);
	// The type whose icon labels the scope header — the scoped type, or the
	// selected entity's own type when an entity is scoped.
	const { data: scopeType } = useEntityType(
		entity?.entity_type ?? typeSlug ?? "",
		orgContext,
	);

	// Clear steps ONE level up the scope hierarchy (entity → its type's events →
	// nothing), it doesn't nuke everything.
	//
	// A single entity's type: from the resolved entity, or parsed from the
	// `<type>/<slug>` scope string as a fallback before it resolves. The `type`
	// search param is read back through decodeEntityTypeParam, so encode the
	// leading `$` (e.g. `$member`) to stay symmetric.
	const scopedEntityType =
		entity?.entity_type ??
		(entityScope
			? decodeEntityTypeParam(entityScope.split("/")[0] ?? "")
			: undefined);
	const entityClearSearch: Record<string, string | undefined> = scopedEntityType
		? { type: scopedEntityType }
		: {};
	const agentClearSearch: Record<string, string | undefined> = {};
	const drillClearSearch: Record<string, string | undefined> = agentScope
		? { agent: agentScope }
		: {};

	const scopeHeader = entityScope ? (
		<ScopeHeader
			icon={
				entity?.entity_type ? (
					<EntityIcon icon={scopeType?.icon} className="h-4 w-4 shrink-0" />
				) : null
			}
			// The entity's type, shown as a clickable crumb before the name:
			// `Task › <name>`. Clicking it drops to that type's events (same target
			// as Clear on a single entity), so the type is always one hop away.
			typeSegment={
				scopedEntityType
					? {
							label: scopeType?.name ?? decodeEntityTypeParam(scopedEntityType),
							search: entityClearSearch,
						}
					: undefined
			}
			label={entity?.name ?? entityScope.split("/").slice(-1)[0]}
			ownerSlug={ownerSlug}
			clearSearch={entityClearSearch}
		/>
	) : behaviorScope && agentScope ? (
		<ScopeHeader
			typeSegment={{
				label: agentLabel ?? "Agent",
				search: agentClearSearch,
			}}
			label={behaviorLabel ?? "Behavior"}
			ownerSlug={ownerSlug}
			clearSearch={drillClearSearch}
		/>
	) : scheduleScope && agentScope ? (
		<ScopeHeader
			typeSegment={{
				label: agentLabel ?? "Agent",
				search: agentClearSearch,
			}}
			label={scheduleLabel ?? "Schedule"}
			ownerSlug={ownerSlug}
			clearSearch={drillClearSearch}
		/>
	) : null;

	const paneBody = (
		<>
			{entityNotFound ? (
				<TabEmptyState
					icon={Boxes}
					title="Entity not found"
					description="This entity no longer exists. Clear the selection to keep browsing."
				/>
			) : null}

			{!entityNotFound ? (
				<EventsTab
					organizationId={organizationId}
					ownerSlug={ownerSlug}
					hideSourceFilter
					entityId={entity?.id}
					scopedEntityTypes={!entityScope && typeSlug ? [typeSlug] : undefined}
				/>
			) : null}
		</>
	);

	if (attentionLens) {
		return (
			<div className="flex min-h-0 min-w-0 flex-1 flex-col gap-4">
				{lensToggle}
				<AttentionBulkBar owner={ownerSlug} />
				<AttentionList
					owner={ownerSlug}
					emptyState={
						<p className="rounded-lg border bg-muted/20 px-3 py-6 text-center text-xs text-muted-foreground">
							Nothing needs attention right now.
						</p>
					}
				/>
			</div>
		);
	}

	return (
		<div className="flex min-h-0 min-w-0 flex-1 flex-col gap-4">
			{lensToggle}
			{scopeHeader ? (
				<div className="sticky top-0 z-20 flex min-w-0 flex-col gap-3 bg-background pt-1">
					{scopeHeader}
				</div>
			) : null}

			{isMemberScope ? (
				<MemberScopeGate ownerSlug={ownerSlug} entityScope={entityScope}>
					{paneBody}
				</MemberScopeGate>
			) : (
				paneBody
			)}
		</div>
	);
}

/** A drill-down breadcrumb with a Clear button. */
function ScopeHeader({
	icon,
	typeSegment,
	label,
	ownerSlug,
	clearSearch,
}: {
	icon?: ReactNode;
	/**
	 * Optional breadcrumb crumb rendered before `label` as `<type> › <label>`.
	 * The crumb links to `search` (one scope level up) so a drill-down always
	 * shows — and can navigate back to — its parent.
	 */
	typeSegment?: { label: string; search: Record<string, string | undefined> };
	label: string;
	ownerSlug: string;
	clearSearch: Record<string, string | undefined>;
}) {
	return (
		<div className="flex min-w-0 items-center gap-1.5 border-l border-border/60 pb-1 pl-3 text-sm">
			{icon}
			{typeSegment ? (
				<>
					<Link
						to="/$owner/activity"
						params={{ owner: ownerSlug }}
						search={typeSegment.search}
						className="shrink-0 font-medium text-muted-foreground transition-colors hover:text-foreground hover:underline"
					>
						{typeSegment.label}
					</Link>
					<ChevronRight className="h-3.5 w-3.5 shrink-0 text-muted-foreground/60" />
				</>
			) : null}
			<span className="min-w-0 truncate font-medium text-foreground">
				{label}
			</span>
			<Button asChild variant="ghost" size="sm" className="h-6 gap-1 px-2">
				<Link
					to="/$owner/activity"
					params={{ owner: ownerSlug }}
					search={clearSearch}
				>
					<X className="h-3.5 w-3.5" />
					Clear
				</Link>
			</Button>
		</div>
	);
}

import { useLocation, useNavigate } from "@tanstack/react-router";
import { useCallback, useMemo } from "react";

type SearchParams = URLSearchParams | Record<string, string | undefined>;

interface UseTabFiltersOptions<TFilters> {
	/** Parse URL search params into typed filters */
	parse: (params: SearchParams) => TFilters;
	/** Serialize typed filters into URL search params */
	serialize: (filters: TFilters) => Record<string, string | undefined>;
	/** Keys to clear when updating filters (filter-specific params) */
	filterKeys: string[];
	/** Whether to also clear clf_* params (default: true) */
	clearClassifications?: boolean;
	/** Merge function: how to combine current filters with updates (default: shallow merge) */
	merge?: (current: TFilters, updates: Partial<TFilters>) => TFilters;
}

/**
 * URL-based filter state management for tab components.
 * Handles parsing from URL, merging updates, serializing back, and navigating.
 */
export function useTabFilters<TFilters>(
	options: UseTabFiltersOptions<TFilters>,
) {
	const {
		parse,
		serialize,
		filterKeys,
		clearClassifications = true,
		merge,
	} = options;
	const navigate = useNavigate();
	const location = useLocation();

	const filters = useMemo(() => {
		const searchEntries = Object.entries(location.search || {}).filter(
			(entry): entry is [string, string] =>
				entry[1] !== undefined && entry[1] !== null,
		);
		const searchParams = new URLSearchParams(searchEntries);
		return parse(searchParams);
	}, [location.search, parse]);

	const updateFilters = useCallback(
		(updates: Partial<TFilters>) => {
			const newFilters = merge
				? merge(filters, updates)
				: ({ ...filters, ...updates } as TFilters);

			const filterParams = serialize(newFilters);

			// Preserve existing non-filter params
			const newSearch: Record<string, unknown> = {};
			for (const [key, value] of Object.entries(location.search || {})) {
				if (value !== undefined && value !== null) {
					newSearch[key] = value;
				}
			}

			// Clear existing filter params
			for (const key of filterKeys) {
				delete newSearch[key];
			}

			// Clear clf_* params
			if (clearClassifications) {
				for (const key of Object.keys(newSearch)) {
					if (key.startsWith("clf_")) {
						delete newSearch[key];
					}
				}
			}

			// Add new filter params
			for (const [key, value] of Object.entries(filterParams)) {
				if (value !== undefined) {
					newSearch[key] = value;
				}
			}

			navigate({
				to: location.pathname as "/",
				search: newSearch,
				replace: true,
			});
		},
		[
			filters,
			serialize,
			filterKeys,
			clearClassifications,
			merge,
			navigate,
			location,
		],
	);

	const clearFilters = useCallback(() => {
		const newSearch: Record<string, unknown> = {};
		for (const [key, value] of Object.entries(location.search || {})) {
			if (value === undefined || value === null) continue;
			if (filterKeys.includes(key)) continue;
			if (clearClassifications && key.startsWith("clf_")) continue;
			newSearch[key] = value;
		}
		navigate({
			to: location.pathname as "/",
			search: newSearch,
			replace: true,
		});
	}, [
		navigate,
		location.pathname,
		location.search,
		filterKeys,
		clearClassifications,
	]);

	return { filters, updateFilters, clearFilters };
}

/**
 * Type-safe utilities for event filter URL parameters
 */

import {
	type ClassificationFilters,
	getParam as getParamValue,
	normalizeClassificationFilters,
	parseClassificationParams,
	parseDateToObject,
	parseInt10,
} from "./filter-utils";

export type { ClassificationFilters };

export interface EventFilters {
	dateRange: [Date, Date] | null;
	engagementRange: [number, number];
	classificationFilters: ClassificationFilters;
	searchQuery: string;
	platforms: string[];
	page: number;
	sortBy: "date" | "score";
	sortOrder: "asc" | "desc";
	reviewStatus: "all" | "user" | "system" | "llm";
	/** Filter by semantic_type — array, matches any. Powers the All/Notifications/Memory bucket selector. */
	semanticTypes: string[];
	windowId: number | null;
	/** Drill-down: scope to a single entity by id (the entity page's "See memory"). */
	entityId: number | null;
	contentIds: number[] | null;
	connectionIds: number[] | null;
	feedIds: number[] | null;
	runIds: number[] | null;
	/** Scope to memory written by this agent (`metadata.agent_id`). Memory sidebar rail. */
	agentId: string | null;
	/** Scope to events produced by any registration of an OAuth client. */
	clientIds: string[] | null;
	/** Internal Connected App drill-down; exact within clientIds and not URL-backed here. */
	mcpActivityId: string | null;
	/** Scope to events analyzed by this behavior (any window). Memory behavior drill-down. */
	behaviorId: number | null;
	beforeOccurredAt: string | null;
	beforeId: number | null;
	afterOccurredAt: string | null;
	afterId: number | null;
	interactionStatus: string | null;
	/**
	 * Scope events to entities of these types. Not URL-backed: set only via the
	 * EventsTab `scopedEntityTypes` prop when browsing a single type in Memory
	 * (`browse_type`). Sent to the API as `entity_types`.
	 */
	entityTypes: string[];
}

export type PartialEventFilters = Partial<EventFilters>;

export function parseEventFiltersFromUrl(
	searchParams: URLSearchParams | Record<string, string | undefined>,
): PartialEventFilters {
	const filters: PartialEventFilters = {};
	const get = (key: string) => getParamValue(searchParams, key);

	// Platforms
	const platformsStr = get("platforms") || get("platform");
	if (platformsStr) {
		const platforms = platformsStr
			.split(",")
			.map((p) => p.trim())
			.filter((p) => p.length > 0);
		if (platforms.length > 0) {
			filters.platforms = platforms;
		}
	}

	// Date range
	const dateStart = get("date_start");
	const dateEnd = get("date_end");
	if (dateStart && dateEnd) {
		const startDate = parseDateToObject(dateStart);
		const endDate = parseDateToObject(dateEnd);
		if (startDate && endDate) {
			filters.dateRange = [startDate, endDate];
		}
	}

	// Engagement range
	const engagementMin = get("engagement_min");
	const engagementMax = get("engagement_max");
	if (engagementMin || engagementMax) {
		const min = parseInt10(engagementMin) ?? 0;
		const max = parseInt10(engagementMax) ?? 100;
		if (min !== 0 || max !== 100) {
			filters.engagementRange = [min, max];
		}
	}

	// Classification filters — JSON format first, then clf_* params
	const classificationFilters: ClassificationFilters = {};
	const classificationsStr = get("classifications");
	if (classificationsStr) {
		try {
			const parsed = JSON.parse(classificationsStr);
			Object.assign(
				classificationFilters,
				normalizeClassificationFilters(parsed),
			);
		} catch (err) {
			console.error("Failed to parse classifications from URL:", err);
		}
	}
	Object.assign(classificationFilters, parseClassificationParams(searchParams));

	if (Object.keys(classificationFilters).length > 0) {
		filters.classificationFilters = classificationFilters;
	}

	// Search query
	const searchQuery = get("q");
	if (searchQuery && searchQuery.trim().length >= 3) {
		filters.searchQuery = searchQuery.trim();
	}

	// Page
	const pageStr = get("page");
	if (pageStr) {
		const page = parseInt10(pageStr);
		if (page != null && page > 0) {
			filters.page = page;
		}
	}

	// Sort options
	const sortBy = get("sort_by");
	if (sortBy === "date" || sortBy === "score") {
		filters.sortBy = sortBy;
	}

	const sortOrder = get("sort_order");
	if (sortOrder === "asc" || sortOrder === "desc") {
		filters.sortOrder = sortOrder;
	}

	// Semantic types (bucket selector: notifications, memory, …)
	const semanticTypesStr = get("semantic_types") || get("semantic_type");
	if (semanticTypesStr) {
		const types = semanticTypesStr
			.split(",")
			.map((t) => t.trim())
			.filter((t) => t.length > 0);
		if (types.length > 0) {
			filters.semanticTypes = types;
		}
	}

	// Review status
	const reviewStatus = get("review_status");
	if (
		reviewStatus === "all" ||
		reviewStatus === "user" ||
		reviewStatus === "system" ||
		reviewStatus === "llm"
	) {
		filters.reviewStatus = reviewStatus;
	}

	// Window ID (from behavior source knowledge link)
	const windowIdStr = get("window_id");
	if (windowIdStr) {
		const windowId = parseInt10(windowIdStr);
		if (windowId != null) filters.windowId = windowId;
	}

	// Entity ID (single-entity drill-down from the entity page's "See memory")
	const entityIdStr = get("entity_id");
	if (entityIdStr) {
		const entityId = parseInt10(entityIdStr);
		if (entityId != null) filters.entityId = entityId;
	}

	// Content IDs (from knowledge item permalink)
	const contentIdsStr = get("content_ids");
	if (contentIdsStr) {
		const ids = contentIdsStr
			.split(",")
			.map((s) => parseInt10(s.trim()))
			.filter((n): n is number => n != null);
		if (ids.length > 0) filters.contentIds = ids;
	}

	// Connection / feed / run drill-down ids (from feed-detail "View in memory")
	for (const [param, key] of [
		["connection_ids", "connectionIds"],
		["feed_ids", "feedIds"],
		["run_ids", "runIds"],
	] as const) {
		const raw = get(param);
		if (!raw) continue;
		const ids = raw
			.split(",")
			.map((s) => parseInt10(s.trim()))
			.filter((n): n is number => n != null);
		if (ids.length > 0) filters[key] = ids;
	}

	// Cursor param: "at=<timestamp>,<id>" (scroll position for infinite scroll)
	const atParam = get("at");
	if (atParam) {
		const lastComma = atParam.lastIndexOf(",");
		if (lastComma > 0) {
			const timestamp = atParam.slice(0, lastComma);
			const id = parseInt10(atParam.slice(lastComma + 1));
			if (timestamp && id != null) {
				filters.beforeOccurredAt = timestamp;
				filters.beforeId = id;
			}
		}
	}

	const interactionStatus = get("interaction_status");
	if (interactionStatus) {
		filters.interactionStatus = interactionStatus;
	}

	const agentId = get("agent") || get("agent_id");
	if (agentId?.trim()) {
		filters.agentId = agentId.trim();
	}

	const clientIdsStr = get("client_ids");
	if (clientIdsStr?.trim()) {
		const ids = clientIdsStr
			.split(",")
			.map((id) => id.trim())
			.filter(Boolean);
		if (ids.length > 0) filters.clientIds = ids;
	}

	// MCP conversation/session drill. The backend only honors it alongside
	// client_ids, so ignore an orphaned value instead of issuing a 400 query.
	const mcpActivityId = get("mcp_activity_id");
	if (mcpActivityId?.trim() && filters.clientIds) {
		filters.mcpActivityId = mcpActivityId.trim();
	}

	const behaviorStr = get("behavior");
	if (behaviorStr) {
		const behaviorId = parseInt10(behaviorStr);
		if (behaviorId != null) filters.behaviorId = behaviorId;
	}

	return filters;
}

export function serializeEventFiltersToSearch(
	filters: PartialEventFilters,
): Record<string, string | undefined> {
	const params: Record<string, string | undefined> = {};

	if (filters.platforms && filters.platforms.length > 0) {
		params.platforms = filters.platforms.join(",");
	}

	if (filters.dateRange) {
		params.date_start = filters.dateRange[0].toISOString().split("T")[0];
		params.date_end = filters.dateRange[1].toISOString().split("T")[0];
	}

	if (filters.engagementRange) {
		if (filters.engagementRange[0] !== 0) {
			params.engagement_min = filters.engagementRange[0].toString();
		}
		if (filters.engagementRange[1] !== 100) {
			params.engagement_max = filters.engagementRange[1].toString();
		}
	}

	if (
		filters.classificationFilters &&
		Object.keys(filters.classificationFilters).length > 0
	) {
		const normalized = normalizeClassificationFilters(
			filters.classificationFilters,
		);
		if (Object.keys(normalized).length > 0) {
			params.classifications = JSON.stringify(normalized);
		}
	}

	if (filters.searchQuery && filters.searchQuery.trim().length >= 3) {
		params.q = filters.searchQuery.trim();
	}

	if (filters.sortBy && filters.sortBy !== "score") {
		params.sort_by = filters.sortBy;
	}

	if (filters.sortOrder && filters.sortOrder !== "desc") {
		params.sort_order = filters.sortOrder;
	}

	if (filters.reviewStatus && filters.reviewStatus !== "all") {
		params.review_status = filters.reviewStatus;
	}

	if (filters.semanticTypes && filters.semanticTypes.length > 0) {
		params.semantic_types = filters.semanticTypes.join(",");
	}

	if (filters.windowId != null) {
		params.window_id = filters.windowId.toString();
	}

	if (filters.entityId != null) {
