import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
	createMemoryHistory,
	createRootRouteWithContext,
	createRoute,
	createRouter,
	Outlet,
	RouterProvider,
	type Router,
} from "@tanstack/react-router";
import { render, waitFor } from "@testing-library/react";
import { HttpResponse, http } from "msw";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { setAuthStateMock } from "@/test/auth-state-mock";
import { server } from "@/test/msw-server";
import { EventsTab } from "./index";

/**
 * Pins the Activity-page freeze: once a second infinite-scroll page lands, the
 * cursor-sync effect writes the scroll position into the URL. That navigation
 * gives the router a fresh `location` object, which gives `updateUrlFilters` a
 * fresh identity, which re-fires the effect — writing the SAME cursor again.
 * TanStack Router still runs a load() cycle for a same-URL replace navigation,
 * minting another fresh location, and the page spins in an endless
 * navigate → render → effect loop ("Page Unresponsive" in Chrome).
 *
 * The assertion counts router navigations after page two settles: one cursor
 * write is expected; a runaway loop shows up as unbounded growth.
 */
describe("EventsTab cursor URL sync", () => {
	let errSpy: ReturnType<typeof vi.spyOn>;
	let readKnowledgeCalls: Array<{ beforeOccurredAt?: string }>;

	function item(id: number, occurredAt: string) {
		return {
			id,
			entity_ids: [],
			origin_id: `origin-${id}`,
			origin_parent_id: null,
			root_origin_id: `origin-${id}`,
			depth: 0,
			rating: null,
			source_url: null,
			permalink: null,
			classifications: {},
			created_at: occurredAt,
			occurred_at: occurredAt,
			platform: "slack",
			semantic_type: "message",
			origin_type: "message",
			payload_type: "text",
			author_name: "Test Author",
			title: `Event ${id}`,
			text_content: `Body ${id}`,
			score: 50,
			metadata: {},
		};
	}

	beforeEach(() => {
		readKnowledgeCalls = [];
		errSpy = vi.spyOn(console, "error").mockImplementation(() => {});

		server.use(
			http.post("*/api/private-org/read_knowledge", async ({ request }) => {
				const body = (await request.json()) as {
					before_occurred_at?: string;
				};
				readKnowledgeCalls.push({
					beforeOccurredAt: body.before_occurred_at,
				});
				if (body.before_occurred_at) {
					return HttpResponse.json({
						content: [
							item(3, "2026-08-05T10:00:00.000Z"),
							item(4, "2026-08-05T09:00:00.000Z"),
						],
						total: 4,
						classification_stats: {},
						page: { limit: 2, offset: 0, has_more: false, has_older: false },
					});
				}
				return HttpResponse.json({
					content: [
						item(1, "2026-08-07T10:00:00.000Z"),
						item(2, "2026-08-07T09:00:00.000Z"),
					],
					total: 4,
					classification_stats: {},
					page: { limit: 2, offset: 0, has_more: true, has_older: true },
				});
			}),
			http.get("*/api/organizations", () =>
				HttpResponse.json({
					organizations: [
						{
							id: "private-org-id",
							name: "Private Org",
							slug: "private-org",
							visibility: "public",
							is_member: true,
						},
					],
				}),
			),
		);
	});

	afterEach(() => {
		errSpy.mockRestore();
		window.history.replaceState({}, "", "/");
	});

	it("writes the scroll cursor to the URL once and then settles", async () => {
		setAuthStateMock("authenticated");
		const queryClient = new QueryClient({
			defaultOptions: {
				queries: { retry: false },
				mutations: { retry: false },
			},
		});

		const rootRoute = createRootRouteWithContext()({
			component: () => <Outlet />,
		});
		const indexRoute = createRoute({
			path: "/$owner",
			getParentRoute: () => rootRoute,
			component: () => (
				<EventsTab organizationId="private-org-id" ownerSlug="private-org" />
			),
		});
		const history = createMemoryHistory({
			initialEntries: ["/private-org?sort_by=date"],
		});
		const router = createRouter({
			routeTree: rootRoute.addChildren([indexRoute]),
			history,
			context: { queryClient },
		});

		let navigations = 0;
		router.subscribe("onBeforeNavigate", () => {
			navigations += 1;
		});

		render(
			<QueryClientProvider client={queryClient}>
				{/** biome-ignore lint/suspicious/noExplicitAny: typed router casted for memory variant */}
				<RouterProvider router={router as any} />
			</QueryClientProvider>,
		);

		// Page one lands; the sentinel's next-page fetch is driven through the
		// query client directly (jsdom's IntersectionObserver stub never fires).
		await waitFor(() => expect(readKnowledgeCalls.length).toBe(1));
		const infiniteQuery = queryClient
			.getQueryCache()
			.getAll()
			.find((q) => q.queryKey[0] === "contents-infinite");
		expect(infiniteQuery).toBeDefined();
		// biome-ignore lint/suspicious/noExplicitAny: infinite query method not on the base type
		await (infiniteQuery as any).fetchNextPage();
		await waitFor(() => expect(readKnowledgeCalls.length).toBe(2));

		// The cursor write for page two is legitimate; let it settle, then give
		// the loop plenty of macrotask rounds to keep spinning if it is unbound.
		await waitFor(() =>
			expect(history.location().search).toContain("at="),
		);
		const settledAt = navigations;
		for (let round = 0; round < 30; round += 1) {
			await new Promise((resolve) => setTimeout(resolve, 0));
		}

		expect(navigations).toBeLessThanOrEqual(settledAt + 1);
		// No duplicate fetches of the same cursor page while settling.
		expect(readKnowledgeCalls.length).toBe(2);
	}, 15_000);
});

