import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
	createMemoryHistory,
	createRootRouteWithContext,
	createRoute,
	createRouter,
	Outlet,
	RouterProvider,
} from "@tanstack/react-router";
import { render, waitFor } from "@testing-library/react";
import { HttpResponse, http } from "msw";
import { beforeEach, describe, expect, it, vi } from "vitest";
import { setAuthStateMock } from "@/test/auth-state-mock";
import { server } from "@/test/msw-server";
import { EventsTab } from "./index";

class CIO {
	static instances: CIO[] = [];
	rootMargin: string;
	constructor(
		readonly cb: any,
		options?: any,
	) {
		this.rootMargin = options?.rootMargin ?? "";
		CIO.instances.push(this);
	}
	observe() {}
	unobserve() {}
	disconnect() {}
	takeRecords() {
		return [];
	}
	root = null;
	thresholds = [];
}

function item(id: number, occurredAt: string) {
	return {
		id,
		entity_ids: [],
		origin_id: `origin-${id}`,
		origin_parent_id: null,
		root_origin_id: `origin-${id}`,
		depth: 0,
		rating: null,
		source_url: null,
		permalink: null,
		classifications: {},
		created_at: occurredAt,
		occurred_at: occurredAt,
		platform: "slack",
		semantic_type: "message",
		origin_type: "message",
		payload_type: "text",
		author_name: "Test Author",
		title: `Event ${id}`,
		text_content: `Body ${id}`,
		score: 50,
		metadata: {},
	};
}

describe("incremental probe", () => {
	beforeEach(() => {
		CIO.instances = [];
		(globalThis as any).IntersectionObserver = CIO;
		vi.spyOn(console, "error");
		server.use(
			http.post("*/api/private-org/read_knowledge", async ({ request }) => {
				const body = (await request.json()) as { before_occurred_at?: string };
				console.error(`RK before=${body.before_occurred_at ?? "none"}`);
				if (body.before_occurred_at) {
					return HttpResponse.json({
						content: [item(3, "2026-08-05T10:00:00.000Z"), item(4, "2026-08-05T09:00:00.000Z")],
						total: 4,
						classification_stats: {},
						page: { limit: 2, offset: 0, has_more: false, has_older: false },
					});
				}
				return HttpResponse.json({
					content: [item(1, "2026-08-07T10:00:00.000Z"), item(2, "2026-08-07T09:00:00.000Z")],
					total: 4,
					classification_stats: {},
					page: { limit: 2, offset: 0, has_more: true, has_older: true },
				});
			}),
			http.get("*/api/organizations", () =>
				HttpResponse.json({
					organizations: [
						{ id: "private-org-id", name: "Private Org", slug: "private-org", visibility: "public", is_member: true },
					],
				}),
			),
		);
	});

	it("steps", async () => {
		setAuthStateMock("authenticated");
		const queryClient = new QueryClient({
			defaultOptions: { queries: { retry: false }, mutations: { retry: false } },
		});
		const rootRoute = createRootRouteWithContext()({ component: () => <Outlet /> });
		const indexRoute = createRoute({
			path: "/$owner",
			getParentRoute: () => rootRoute,
			component: () => <EventsTab organizationId="private-org-id" ownerSlug="private-org" />,
		});
		const history = createMemoryHistory({ initialEntries: ["/private-org"] });
		const router = createRouter({
			routeTree: rootRoute.addChildren([indexRoute]),
			history,
			context: { queryClient },
		});
		console.error("STEP render");
		render(
			<QueryClientProvider client={queryClient}>
				{/* biome-ignore lint/suspicious/noExplicitAny: memory router */}
				<RouterProvider router={router as any} />
			</QueryClientProvider>,
		);
		console.error("STEP subscribe");
		let navigations = 0;
		router.subscribe("onBeforeNavigate", () => {
			navigations += 1;
		});
		console.error("STEP wait-page1");
		await waitFor(
			() => {
				expect(document.body.textContent).toContain("Event 1");
			},
			{ timeout: 3000 },
		);
		console.error(`STEP page1-rendered navigations=${navigations} io=${CIO.instances.length}`);
		await new Promise((r) => setTimeout(r, 300));
		console.error(`STEP settle300 navigations=${navigations} io=${CIO.instances.length} margins=${CIO.instances.map((i) => i.rootMargin).join("|")}`);
		expect(true).toBe(true);
	}, 10000);
});

