// PAT-in-URL handoff: when a deep link carries `?lobu_token=<PAT>`, swap it
// for a session cookie before the SPA boots. The server endpoint validates
// the PAT, mints a Better Auth session, and 302s back to `next` (the
// original path with the token stripped). Used by the macOS menu-bar app
// and operators sharing pre-authed deep links.
const tokenParam = new URLSearchParams(window.location.search).get(
	"lobu_token",
);
if (tokenParam) {
	const url = new URL(window.location.href);
	url.searchParams.delete("lobu_token");
	const next = url.pathname + url.search + url.hash;
	window.location.replace(
		`/api/exchange-token?token=${encodeURIComponent(tokenParam)}&next=${encodeURIComponent(next)}`,
	);
	// Halt SPA init until the navigation lands so we don't briefly render the
	// login screen against the unauthenticated cookie state.
	await new Promise(() => {});
}

