// Update URL with scroll position when new pages are loaded (date feed mode).
// Guard against re-writing a cursor that already matches the URL: the
// navigation mints a fresh `location`, which gives `updateUrlFilters` a
// fresh identity and re-fires this effect; without the guard the effect
// writes the same cursor forever and the page spins into an endless
// navigate → render → effect loop ("Page Unresponsive").
const lastPage = infiniteData?.pages[infiniteData.pages.length - 1];
const lastLoadedItem = lastPage?.content[lastPage.content.length - 1];
useEffect(() => {
	if (!useDateFeed || !lastLoadedItem || infiniteData?.pages.length === 1)
		return;
	if (
		urlFilters.beforeOccurredAt === lastLoadedItem.occurred_at &&
		urlFilters.beforeId === lastLoadedItem.id
	)
		return;
	updateUrlFilters({
		beforeOccurredAt: lastLoadedItem.occurred_at,
		beforeId: lastLoadedItem.id,
	});
}, [
	lastLoadedItem?.id,
	useDateFeed,
	updateUrlFilters,
	infiniteData?.pages.length,
	lastLoadedItem,
	urlFilters.beforeOccurredAt,
	urlFilters.beforeId,
]);

