import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import {
	createMemoryHistory,
	createRootRouteWithContext,
	createRoute,
	createRouter,
	Outlet,
	RouterProvider,
} from "@tanstack/react-router";
import { render, waitFor } from "@testing-library/react";
import { HttpResponse, http } from "msw";
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { setAuthStateMock } from "@/test/auth-state-mock";
import { server } from "@/test/msw-server";
import { EventsTab } from "./index";

/**
 * Pins the Activity-page freeze (scroll down a little → "Page Unresponsive").
 *
 * When the second infinite-scroll page lands, the cursor-sync effect writes the
 * scroll position into the URL (`?at=<ts>,<id>`). That navigation gives the
 * router a fresh `location`, which gives `updateUrlFilters` a fresh identity,
 * which re-fires the effect — writing the SAME cursor again. TanStack Router
 * still runs a load() cycle for a same-URL replace navigation, minting another
 * fresh location, and the page spins in an endless navigate → render → effect
 * loop. Verified in a real browser: unfixed code freezes the tab; with the
 * equality guard below, the cursor is written exactly once.
 *
 * The test asserts the settle is bounded: one history rewrite for the cursor,
 * no further rewrites or fetches while the page sits and while the user
 * scrolls back up.
 */

/** IntersectionObserver stub that lets the test fire the sentinel callback —
 * the global setup stub never intersects, so next-page fetches would never
 * start. Only instances with the sentinel's 400px rootMargin are fired. */
class ControllableIntersectionObserver {
	static instances: ControllableIntersectionObserver[] = [];
	readonly rootMargin: string;

	constructor(
		private readonly callback: IntersectionObserverCallback,
		options?: IntersectionObserverInit,
	) {
		this.rootMargin = options?.rootMargin ?? "";
		ControllableIntersectionObserver.instances.push(this);
	}

	observe() {}
	unobserve() {}
	disconnect() {}
	takeRecords() {
		return [];
	}

	root = null;
	thresholds = [];

	fire(isIntersecting: boolean) {
		// biome-ignore lint/suspicious/noExplicitAny: minimal synthetic entry
		this.callback([{ isIntersecting } as any], this as any);
	}

	static fireSentinels() {
		for (const instance of ControllableIntersectionObserver.instances) {
			if (instance.rootMargin === "400px") instance.fire(true);
		}
	}
}

describe("EventsTab cursor URL sync", () => {
	let errSpy: ReturnType<typeof vi.spyOn>;
	let readKnowledgeCalls: Array<{ beforeOccurredAt?: string }>;

	function item(id: number, occurredAt: string) {
		return {
			id,
			entity_ids: [],
			origin_id: `origin-${id}`,
			origin_parent_id: null,
			root_origin_id: `origin-${id}`,
			depth: 0,
			rating: null,
			source_url: null,
			permalink: null,
			classifications: {},
			created_at: occurredAt,
			occurred_at: occurredAt,
			platform: "slack",
			semantic_type: "message",
			origin_type: "message",
			payload_type: "text",
			author_name: "Test Author",
			title: `Event ${id}`,
			text_content: `Body ${id}`,
			score: 50,
			metadata: {},
		};
	}

	beforeEach(() => {
		readKnowledgeCalls = [];
		ControllableIntersectionObserver.instances = [];
		// biome-ignore lint/suspicious/noExplicitAny: test-local observer swap
		(globalThis as any).IntersectionObserver = ControllableIntersectionObserver;
		errSpy = vi.spyOn(console, "error").mockImplementation(() => {});

		server.use(
			http.post("*/api/private-org/read_knowledge", async ({ request }) => {
				const body = (await request.json()) as {
					before_occurred_at?: string;
				};
				readKnowledgeCalls.push({
					beforeOccurredAt: body.before_occurred_at,
				});
				if (body.before_occurred_at) {
					return HttpResponse.json({
						content: [
							item(3, "2026-08-05T10:00:00.000Z"),
							item(4, "2026-08-05T09:00:00.000Z"),
						],
						total: 4,
						classification_stats: {},
						page: { limit: 2, offset: 0, has_more: false, has_older: false },
					});
				}
				return HttpResponse.json({
					content: [
						item(1, "2026-08-07T10:00:00.000Z"),
						item(2, "2026-08-07T09:00:00.000Z"),
					],
					total: 4,
					classification_stats: {},
					page: { limit: 2, offset: 0, has_more: true, has_older: true },
				});
			}),
			http.get("*/api/organizations", () =>
				HttpResponse.json({
					organizations: [
						{
							id: "private-org-id",
							name: "Private Org",
							slug: "private-org",
							visibility: "public",
							is_member: true,
						},
					],
				}),
			),
		);
	});

	afterEach(() => {
		errSpy.mockRestore();
		window.history.replaceState({}, "", "/");
	});

	it("writes the scroll cursor once when page two lands, then settles", async () => {
		setAuthStateMock("authenticated");
		const queryClient = new QueryClient({
			defaultOptions: {
				queries: { retry: false },
				mutations: { retry: false },
			},
		});

		const rootRoute = createRootRouteWithContext()({
			component: () => <Outlet />,
		});
		const indexRoute = createRoute({
			path: "/$owner",
			getParentRoute: () => rootRoute,
			component: () => (
				<EventsTab organizationId="private-org-id" ownerSlug="private-org" />
			),
		});
		const history = createMemoryHistory({
			initialEntries: ["/private-org"],
		});
		// Count every history rewrite — the runaway loop's signature is unbounded
		// same-URL rewrites after the cursor lands.
		let rewrites = 0;
		const origReplace = history.replace.bind(history);
		history.replace = (...args: Parameters<typeof origReplace>) => {
			rewrites += 1;
			return origReplace(...args);
		};
		const router = createRouter({
			routeTree: rootRoute.addChildren([indexRoute]),
			history,
			context: { queryClient },
		});

		render(
			<QueryClientProvider client={queryClient}>
				{/** biome-ignore lint/suspicious/noExplicitAny: typed router casted for memory variant */}
				<RouterProvider router={router as any} />
			</QueryClientProvider>,
		);

		// Page one lands; then the sentinel intersects (user scrolls down a bit)
		// and page two loads through the component's real fetch path.
		await waitFor(() => expect(readKnowledgeCalls.length).toBe(1));
		await waitFor(() =>
			expect(
				ControllableIntersectionObserver.instances.some(
					(i) => i.rootMargin === "400px",
				),
			).toBe(true),
		);
		ControllableIntersectionObserver.fireSentinels();
		await waitFor(() => expect(readKnowledgeCalls.length).toBe(2));

		// The cursor write for page two is legitimate and must land exactly once.
		await waitFor(() =>
			expect(history.location().search).toContain("at="),
		);
		expect(history.location().search).toContain(
			encodeURIComponent("2026-08-05T09:00:00.000Z"),
		);
		const rewritesAtSettle = rewrites;
		expect(rewritesAtSettle).toBeGreaterThanOrEqual(1);

		// Give a would-be loop plenty of macrotask rounds, then simulate the
		// user scrolling back up (re-render churn without new data). Nothing may
